        private static string Class(int Class)
        {
            if (Class >= 1000 && Class <= 1057) { return "Trojan"; }
            if (Class >= 2000 && Class <= 2057) { return "Warrior"; }
            if (Class >= 4000 && Class <= 4057) { return "Archer"; }
            if (Class >= 5000 && Class <= 5057) { return "Ninja"; }
            if (Class >= 6000 && Class <= 6057) { return "Monk"; }
            if (Class >= 7000 && Class <= 7057) { return "Pirate"; }
            if (Class >= 8000 && Class <= 8057) { return "Dragon-Warrior"; }
            if (Class >= 16000 && Class <= 16057) { return "Wind-Walker"; }
            if (Class >= 10000 && Class <= 14057) { return "WaterTaoist"; }
            if (Class >= 14002 && Class <= 14057) { return "FireTaoist"; }
            if (Class >= 9000 && Class <= 9057) { return "ThunderStriker"; }
            if (Class == 0) { return "Not selected"; }
            return "Not selected";
        }

        [NpcAttribute(NpcID.AllinceWarContractor)]
        public static void AllinceWarContractor(Client.GameClient client, ServerSockets.Packet stream, byte Option, string Input, uint id)
        {
            DateTime Now64 = DateTime.Now;
            Dialog data = new Dialog(client, stream);
            switch (Option)
            {
                case 0:
                    {
                        data.AddText("--------------------------------------------------------------------------------------------------------\n");
                        data.AddText("Hello Contractor " + client.Player.Name + ", Welcome to [" + Program.ServerConfig.ServerName + " Server] I will be glad to tell yo about this Event.\n");
                        data.AddText("This Event This our way to test our player's strength we hope you will enjoy it\n");
                        data.AddText("The rules are very easy the the guild who that get more points in the 4 Stages Wins\n");
                        data.AddText("--------------------------------------------------------------------------------------------------------\n");
                        data.AddOption("Global Rank", 1); 
                        data.AddOption("Send Me to war", 2);
                        data.AddOption("Just passing by..", 255);
                        data.AddAvatar(265).FinalizeDialog();
                        break;
                    }
                case 2:
                    {
                        switch (MsgSchedules._allianceWarManager.CurrentAction)
                        {
                            case DeadRabbitProject.Events.AllianceWar.MsgAllianceWarMCP.ActionType.StageOne:
                                {
                                    client.Teleport(87, 78, 10723);
                                    break;
                                }
                            case DeadRabbitProject.Events.AllianceWar.MsgAllianceWarMCP.ActionType.StageTwo:
                                {
                                    client.Teleport(158, 149, 10723);
                                    break;
                                }
                            case DeadRabbitProject.Events.AllianceWar.MsgAllianceWarMCP.ActionType.StageThree:
                                {
                                    client.Teleport(158, 84, 10723);
                                    break;
                                }
                            case DeadRabbitProject.Events.AllianceWar.MsgAllianceWarMCP.ActionType.StageFour:
                                {
                                    client.Teleport(74, 151, 10723);
                                    break;
                                }
                            default:
                                {
                                    client.CreateBoxDialog("Allince War is closed Right Now try in another time");
                                    break;
                                }
                        }
                        break;
                    }
            }
        }

        [NpcAttribute(NpcID.HuntersGuild)]
        public static void HuntersGuild(Client.GameClient client, ServerSockets.Packet stream, byte Option, string Input, uint id)
        {
            DateTime Now64 = DateTime.Now;
            Dialog data = new Dialog(client, stream);
            switch (Option)
            {
                case 0:
                    {
                        if (DeadRabbitProject.Hunters.HuntersRank.IsHunter(client.Player.UID))
                        {
                            data.AddText("--------------------------------------------------------------------------------------------------------\n");
                            data.AddText("Hello Hunter " + client.Player.Name + ", Welcome to [" + Program.ServerConfig.ServerName + " Server] I will be glad to tell yo about this Event.\n");
                            data.AddText("This Event This our way to test our player's strength we hope you will enjoy it\n");
                            data.AddText("The rules are very easy hunt or be hunted\n");
                            data.AddText("The Story started when the war started between the realms, you hope you can protect our realm from outside monsters\n");
                            data.AddText("--------------------------------------------------------------------------------------------------------\n");
                            data.AddOption("Global Rank", 1);
                            data.AddOption("Give me Teleportation Item", 2);
                            data.AddOption("Just passing by..", 255);
                            data.AddAvatar(265).FinalizeDialog();
                        }
                        else
                        {
                            data.AddText("--------------------------------------------------------------------------------------------------------\n");
                            data.AddText("Hello Dear [ " + client.Player.Name + " ], Welcome to [ " + Program.ServerConfig.ServerName + " Server] I will be glad to tell yo about this Event.\n");
                            data.AddText("This Event This our way to test our player's strength we hope you will enjoy it\n");
                            data.AddText("The rules are very easy hunt or be hunted\n");
                            data.AddText("The Story started when the war started between the realms, you hope you can protect our realm from outside monsters\n");
                            data.AddText("--------------------------------------------------------------------------------------------------------\n");
                            data.AddOption("Global Rank", 1);
                            data.AddOption("I want to become a hunter", 3);
                            data.AddOption("Just passing by..", 255);
                            data.AddAvatar(265).FinalizeDialog();
                        }
                       
                        break;
                    }
                case 1:
                    {

                        DeadRabbitProject.Hunters.HuntersRank.GetHuntersRank();
                        // Combine the data into a list of objects for easier sorting
                        var hunters = DeadRabbitProject.Hunters.HuntersRank.HunterName.Select((name, index) => new
                        {
                            Name = name,
                            Rank = DeadRabbitProject.Hunters.HuntersRank.HunterRank[index],
                            Score = DeadRabbitProject.Hunters.HuntersRank.HunterScore[index],
                            Guild = DeadRabbitProject.Hunters.HuntersRank.HunterGuild[index]
                        }).ToList();

                        // Sort the hunters by score in descending order
                        var sortedHunters = hunters.OrderByDescending(h => h.Score).Take(10).ToList();

                        // Display the sorted hunters from 1 to 10
                        data.AddText("--------------------------------------------------------------------------------------------------------\n");
                        data.AddText("Rank Number      Hunter Name     Hunter Score    HunterRank     Hunter Guild \n");
                        data.AddText("--------------------------------------------------------------------------------------------------------\n");
                        for (int i = 0; i < sortedHunters.Count; i++)
                        {
                            var hunter = sortedHunters[i];
                            data.AddText($"  {i+1}          {hunter.Name}            {hunter.Score}             {hunter.Rank}           {hunter.Guild}\n");
                        }
                        data.AddOption("Thank you.", 255);
                        data.AddAvatar(265).FinalizeDialog();
                        break;
                    }       
                case 2:
                    {
                        if(client.Inventory.HaveSpace(1))
                        {
                            client.Inventory.Add(stream, 720828, 1); // you give MemoryAgate to the player
                            client.CreateBoxDialog("Congratulation  " + client.Player.Name + ", check your Inventory \n");
                        }
                        else
                        {
                            client.CreateBoxDialog("You Need at least one place in your Inventory");
                        }       
                        break;
                    }
                case 3:
                    {
                        if(client.Inventory.Contain(711145, 3)) //change item id As you like
                        {
                            client.Inventory.Remove(711145, 3,stream); //change item id As you like
                            if(client.Player.MyGuild != null)
                            {
                                DeadRabbitProject.Hunters.HuntersRank.RegisterHunters(client.Player.UID, client.Player.Name, client.Player.BattlePower, client.Player.MyGuild.GuildName);
                            }
                            else
                            {
                                DeadRabbitProject.Hunters.HuntersRank.RegisterHunters(client.Player.UID, client.Player.Name, client.Player.BattlePower, "No Guild");
                            }
                            data.AddText("--------------------------------------------------------------------------------------------------------\n");
                            data.AddText("Congratulation  " + client.Player.Name + ", You have became a hunter now your rank is [ E ] to upgrade your rank you should kill any monster appears when you gates opens \n");
                            data.AddText("--------------------------------------------------------------------------------------------------------\n");
                            data.AddOption("Thank you very much", 255);
                            data.AddAvatar(265).FinalizeDialog();
                        }
                        else
                        {
                            data.AddText("--------------------------------------------------------------------------------------------------------\n");
                            data.AddText("Dear  " + client.Player.Name + ", to became a Hunter you should have collected the 3 fragments from the monsters\n");
                            data.AddText("--------------------------------------------------------------------------------------------------------\n");
                            data.AddOption("I will think about that...", 255);
                            data.AddAvatar(265).FinalizeDialog();
                        }                       
                        break;
                    }
            }
        }
        [NpcAttribute(NpcID.RoyalePass)]
        public static void RoyalePass(Client.GameClient client, ServerSockets.Packet stream, byte Option, string Input, uint id)
        {
            DateTime Now64 = DateTime.Now;
            Dialog data = new Dialog(client, stream);
            switch (Option)
            {
                case 0:
                    {
                        if (DeadRabbitProject.RoyalePass.RoyalePassSystem.HasProfile(client.Player.UID))
                        {

                        }
                        else
                        {
                            new DBFunctionality.MySqlCommand(DBFunctionality.MySqlCommandType.INSERT).Insert("royalepass").Insert("UID", client.Player.UID).Insert("Name", client.Player.Name).Insert("Subscription", 0).Insert("Claimed", 0).Execute();
                        }
                        data.AddText("--------------------------------------------------------------------------------------------------------\n");
                        data.AddText("Hello " + client.Player.Name + ", Welcome to [" + Program.ServerConfig.ServerName + " Server] I will be glad to tell yo about this Event.\n");
                        data.AddText("This is BattlePass Event We have to Options Free One And Paid One.\n");
                        data.AddText("The Free BattlePass Will give you one gift everyday, the Paid BattlePass Will give you one gift also but much Better\n");
                        data.AddText("--------------------------------------------------------------------------------------------------------\n");
                        data.AddOption("Claim Daily Gift", 1);
                        data.AddOption("Subscription", 2);
                        data.AddOption("Just passing by..", 255);
                        data.AddAvatar(265).FinalizeDialog();
                        break;
                    }
                case 1:
                    {
                        if(DeadRabbitProject.RoyalePass.RoyalePassSystem.HasGift(client.Player.UID,0))
                        {
                            DeadRabbitProject.RoyalePass.RoyalePassGifts.SetDay(Now64.Day);
                            if (DeadRabbitProject.RoyalePass.RoyalePassSystem.SubscriptionStatus(client.Player.UID, DeadRabbitProject.RoyalePass.RoyalePassSystem.Subscription.FreePass))
                            {
                                if (client.Inventory.HaveSpace(1))
                                {
                                    uint ItemID = DeadRabbitProject.RoyalePass.RoyalePassGifts.FreePass[DeadRabbitProject.RoyalePass.RoyalePassGifts.Day];
                                    uint PaidSubItemID = DeadRabbitProject.RoyalePass.RoyalePassGifts.RoyalePass[DeadRabbitProject.RoyalePass.RoyalePassGifts.Day];
                                    data.AddText("--------------------------------------------------------------------------------------------------------\n");
                                    data.AddText("Congratulations " + client.Player.Name + ", you can claim [" + DeadRabbitProject.RoyalePass.RoyalePassGifts.GetItemName(ItemID) + "] or you want to upgrate your Subscription to get [" + DeadRabbitProject.RoyalePass.RoyalePassGifts.GetItemName(PaidSubItemID) + "] ? \n");
                                    data.AddText("--------------------------------------------------------------------------------------------------------\n");
                                    data.AddOption("Claim", 11);
                                    data.AddOption("Upgrade My Subscription", 19);
                                    data.AddAvatar(263).FinalizeDialog();
                                   
                                }
                                else
                                {
                                    data.AddText("You Must Have one Space In your Inventory \n");
                                    data.AddOption("My Bad",255);
                                    data.AddAvatar(263).FinalizeDialog();
                                }

                            }
                            if (DeadRabbitProject.RoyalePass.RoyalePassSystem.SubscriptionStatus(client.Player.UID, DeadRabbitProject.RoyalePass.RoyalePassSystem.Subscription.RoyalePass))
                            {
                                if (client.Inventory.HaveSpace(1))
                                {
                                    uint PaidSubItemID = DeadRabbitProject.RoyalePass.RoyalePassGifts.RoyalePass[DeadRabbitProject.RoyalePass.RoyalePassGifts.Day];
                                    data.AddText("--------------------------------------------------------------------------------------------------------\n");
                                    data.AddText("Congratulations " + client.Player.Name + ", you can claim [" + DeadRabbitProject.RoyalePass.RoyalePassGifts.GetItemName(PaidSubItemID) + "], Thank you for buying this future. \n");
                                    data.AddText("--------------------------------------------------------------------------------------------------------\n");
                                    data.AddOption("Claim", 12);
                                    data.AddAvatar(263).FinalizeDialog();

                                }
                                else
                                {
                                    data.AddText("You Must Have one Space In your Inventory \n");
                                    data.AddOption("My Bad",255);
                                    data.AddAvatar(263).FinalizeDialog();
                                }
                            }
                        }
                        else
                        {
                            data.AddText("Unfortunately,["+client.Player.Name+"] you don't have anygifts or you already claimed your gift already \n");
                            data.AddOption("My Bad",255);
                            data.AddAvatar(263).FinalizeDialog();
                        }
                        
                        break;
                    }
                case 11:
                    {
                        uint ItemID = DeadRabbitProject.RoyalePass.RoyalePassGifts.FreePass[DeadRabbitProject.RoyalePass.RoyalePassGifts.Day];
                        uint ItemCount = DeadRabbitProject.RoyalePass.RoyalePassGifts.GetGiftCount(ItemID, DeadRabbitProject.RoyalePass.RoyalePassSystem.Subscription.FreePass);
                        new DBFunctionality.MySqlCommand(DBFunctionality.MySqlCommandType.UPDATE).Update("royalepass").Set("Claimed", "1").Where("UID", client.Player.UID).Execute();
                        if (!string.IsNullOrEmpty(DeadRabbitProject.RoyalePass.RoyalePassGifts.GetItemName(ItemID)) && DeadRabbitProject.RoyalePass.RoyalePassGifts.GetItemName(ItemID).IndexOf("Online Point", StringComparison.OrdinalIgnoreCase) >= 0)
                        {
                            client.Player.OnlineMinutes += ItemID;
                            data.AddText("--------------------------------------------------------------------------------------------------------\n");
                            data.AddText("Congratulations " + client.Player.Name + ", you got [" + DeadRabbitProject.RoyalePass.RoyalePassGifts.GetItemName(ItemID) + "], you can get much better items if you bought the [RoyalePass] for 1 USD \n");
                            data.AddText("--------------------------------------------------------------------------------------------------------\n");
                            data.AddOption("Thanks", 255);
                            data.AddAvatar(263).FinalizeDialog();
                        }
                        else
                        {
                            client.Inventory.AddItemWitchStack(ItemID, 0, ItemCount, stream);
                            data.AddText("--------------------------------------------------------------------------------------------------------\n");
                            data.AddText("Congratulations " + client.Player.Name + ", you got [" + string.Format("{0}x " + DeadRabbitProject.RoyalePass.RoyalePassGifts.GetItemName(ItemID) + " ", ItemCount) + "], you can get much better items if you bought the [RoyalePass] for 1 USD \n");
                            data.AddText("--------------------------------------------------------------------------------------------------------\n");
                            data.AddOption("Thanks", 255);
                            data.AddAvatar(263).FinalizeDialog();
                        }

                       
                       
                        break;
                    }
                case 12:
                    {
                        uint PaidSubItemID = DeadRabbitProject.RoyalePass.RoyalePassGifts.RoyalePass[DeadRabbitProject.RoyalePass.RoyalePassGifts.Day];
                        uint ItemCount = DeadRabbitProject.RoyalePass.RoyalePassGifts.GetGiftCount(PaidSubItemID, DeadRabbitProject.RoyalePass.RoyalePassSystem.Subscription.RoyalePass);
                        new DBFunctionality.MySqlCommand(DBFunctionality.MySqlCommandType.UPDATE).Update("royalepass").Set("Claimed", "1").Where("UID", client.Player.UID).Execute();
                        if (!string.IsNullOrEmpty(DeadRabbitProject.RoyalePass.RoyalePassGifts.GetItemName(PaidSubItemID)) && DeadRabbitProject.RoyalePass.RoyalePassGifts.GetItemName(PaidSubItemID).IndexOf("Online Point", StringComparison.OrdinalIgnoreCase) >= 0)
                        {
                            client.Player.OnlineMinutes += PaidSubItemID;
                            data.AddText("--------------------------------------------------------------------------------------------------------\n");
                            data.AddText("Congratulations " + client.Player.Name + ", you got [" + DeadRabbitProject.RoyalePass.RoyalePassGifts.GetItemName(PaidSubItemID) + "].\n");
                            data.AddText("Thank you for Buying this Future and Supporting the Server.\n");
                            data.AddText("--------------------------------------------------------------------------------------------------------\n");
                            data.AddOption("Thanks", 255);
                            data.AddAvatar(263).FinalizeDialog();
                        }
                        else
                        {
                            client.Inventory.AddItemWitchStack(PaidSubItemID, 0, ItemCount, stream);
                            data.AddText("--------------------------------------------------------------------------------------------------------\n");
                            data.AddText("Congratulations " + client.Player.Name + ", you got [" + string.Format("{0}x " + DeadRabbitProject.RoyalePass.RoyalePassGifts.GetItemName(PaidSubItemID) + " ", ItemCount) + "]. \n");
                            data.AddText("Thank you for Buying this Future and Supporting the Server.\n");
                            data.AddText("--------------------------------------------------------------------------------------------------------\n");
                            data.AddOption("Thanks", 255);
                            data.AddAvatar(263).FinalizeDialog();
                        }
                       
                       
                        break;
                    }

                case 2:
                    {
                        if (DeadRabbitProject.RoyalePass.RoyalePassSystem.SubscriptionStatus(client.Player.UID, DeadRabbitProject.RoyalePass.RoyalePassSystem.Subscription.FreePass))
                        {
                            data.AddText("--------------------------------------------------------------------------------------------------------\n");
                            data.AddText("Hello " + client.Player.Name + ", Your Subscription is status is : [FreePass]\n");
                            data.AddText("The Free BattlePass Will give you one gift everyday, the Paid BattlePass Will give you one gift also but much Better\n");
                            data.AddText("--------------------------------------------------------------------------------------------------------\n");
                            data.AddOption("Upgrade my Subscription", 20);
                            data.AddOption("Just passing by..", 255);
                            data.AddAvatar(265).FinalizeDialog();
                        }
                        else
                        {
                            data.AddText("--------------------------------------------------------------------------------------------------------\n");
                            data.AddText("Hello " + client.Player.Name + ", Your Subscription is status is : [RoyalePass]\n");
                            data.AddText("The Free BattlePass Will give you one gift everyday, the Paid BattlePass Will give you one gift also but much Better\n");
                            data.AddText("--------------------------------------------------------------------------------------------------------\n");
                            data.AddOption("Thanks", 255);
                            data.AddAvatar(265).FinalizeDialog();
                        }
                        break;
                    }
                case 19:
                    {

                        data.AddText("--------------------------------------------------------------------------------------------------------\n");
                        data.AddText("Dear " + client.Player.Name + ", to Upgrade your Subscription you need to pay 1$ or 50 EGP\n");
                        data.AddText("--------------------------------------------------------------------------------------------------------\n");
                        data.AddOption("Upgrade", 20);
                        data.AddOption("I will think about that...", 255);
                        data.AddAvatar(265).FinalizeDialog();
                        break;
                    }
                case 20:
                    {
                        if(client.Player.DonatePoint >= 50)
                        {
                            client.Player.DonatePoint -= 50;
                            DeadRabbitProject.RoyalePass.RoyalePassSystem.UpdateSub(client.Player.UID);
                            data.AddText("--------------------------------------------------------------------------------------------------------\n");
                            data.AddText("Congratulations " + client.Player.Name + ", You Successfully upgraded your Subscription, You can now Claim Your Gift Again.\n");
                            data.AddText("--------------------------------------------------------------------------------------------------------\n");
                            data.AddOption("My Subscription", 2);
                            data.AddOption("Thanks", 255);
                            data.AddAvatar(265).FinalizeDialog();
                        }
                        else
                        {
                            data.AddText("--------------------------------------------------------------------------------------------------------\n");
                            data.AddText("Unfortunately, " + client.Player.Name + ", You don't have enough [DonatePoints] to upgrate your subscription \n");
                            data.AddText("you need to donate to get [DonatePoints], to donate you need to contact the [GM].\n");
                            data.AddText("you have ["+client.Player.DonatePoint+"].\n");
                            data.AddText("--------------------------------------------------------------------------------------------------------\n");
                            data.AddOption("My bad..", 255);
                            data.AddAvatar(265).FinalizeDialog();
                        }
                        break;
                    }
            }
        }
