        [NpcAttribute(NpcID.HalloweenCarnival)]
        private static void HalloweenCarnival(Client.GameClient client, ServerSockets.Packet stream, byte Option, string Input, uint id)
        {
            Dialog dialog = new Dialog(client, stream);
            switch (Option)
            {
                case 0:
                    {
                        dialog.AddText("The Tale of Old Man Eli and the Haunted Hollow : \n");
                        dialog.AddText("As the players wander through a sleepy village tucked deep within the autumn woods, they encounter an elderly man sitting on the steps of an abandoned chapel. He's a small figure cloaked in a thick, moth-eaten jacket, his face a labyrinth of wrinkles illuminated by the lantern light. He waves a bony hand to beckon them closer. \n");
                        dialog.AddText("Ah, travelers! Perfect timing.It’s All Hallows’ Eve, the night when the veil between our world and theirs thins to a hair.Have a seat.Let me tell you of the creatures that lurk in the Hollow, for tonight they roam free \n") ;
                        dialog.AddText("The old man introduces himself as Eli, once a hunter and now the last living resident of Hollowridge. He explains that every Halloween, monsters emerge from the forest shadows and stroll down from the hills, as if visiting an ancient, haunted homeland. Most folks left the village years ago, fearing the creatures, but Eli stayed behind, saying he’s too stubborn to leave and too curious to miss the show. \n") ;
                        dialog.AddText("------------------------------------- HalloweenCarnival Guide ------------------------------------------\n");
                        dialog.AddText("There are three monsters in the Hollow, each more terrible than the last, Eli whispers, his eyes twinkling with a mixture of fear and delight.\n");
                        dialog.AddText("---------------------------------------- HalloweenCarnival ---------------------------------------------\n");
                        dialog.AddText("Requirement: 2nd rebirth, Level 15+\n");
                        dialog.AddText("Expire Date: Never\n");
                        dialog.AddOption("1-The Lantern Bride", 1);
                        dialog.AddOption("2-The Harvest Man", 2);
                        dialog.AddOption("3-The Hollow Watcher", 2);
                        dialog.AddOption("I'm just passing by", 255);
                        dialog.AddAvatar(63);
                        dialog.FinalizeDialog();
                        break;
                    }
                case 1:
                    {
                        dialog.AddText("1. The Lantern Bride \n");
                        dialog.AddText("First, there’s the Lantern Bride. Folks say she’s a woman from centuries past, jilted on her wedding night and left to die in the woods. She wanders with her lantern, still wearing her tattered wedding gown, calling out in a soft, sorrowful voice. \n");
                        dialog.AddText("If anyone listens too long, they’ll be compelled to follow her, lost in a trance as she leads them deeper into the woods, away from warmth, light, and safety. Eli tells the players that they can recognize her by the faint glow of her lantern and the sound of her chilling whispers on the wind. \n");
                        dialog.AddOption("I Will Hunt Her Down", 10);
                        dialog.AddOption("Need some time to think", 255);
                        dialog.AddAvatar(63);
                        dialog.FinalizeDialog();
                        break;
                    }
                case 2:
                    {
                        dialog.AddText("2. The Harvest Man \n");
                        dialog.AddText("Eli lowers his voice further : Then there’s the Harvest Man. A scarecrow come to life, built of rotting straw and rusted farming tools. He’s an angry thing, always moving with a purpose, as though he’s on a never-ending quest for vengeance. Some say he’s got a heart full of spite for those who wronged him, others say he’s just looking for a place to rest—but he never finds it. \n");
                        dialog.AddText("Eli swears that the Harvest Man can only be stopped if someone tells him a secret he's never heard before. But no one’s figured out what secrets satisfy him, because those who try never return. \n");
                        dialog.AddOption("I Will Hunt Him Down", 11);
                        dialog.AddOption("Need some time to think", 255);
                        dialog.AddAvatar(63);
                        dialog.FinalizeDialog();
                        break;
                    }
                case 3:
                    {
                        dialog.AddText("3. The Hollow Watcher \n");
                        dialog.AddText("Finally, Eli leans in and almost whispers : he Hollow Watcher is the worst of them all. No one knows what it looks like, ‘cause it’s always lurking just out of sight. They say it’s a spirit from the earth itself, ancient and forgotten, watching over Hollowridge with a gaze that can freeze your bones. If you catch a glimpse of it, you’re done for; your soul gets drawn out to join the trees, roots, and stones of the Hollow forever. \n");
                        dialog.AddText("Eli’s voice quivers a bit as he says this last part, and he glances over his shoulder as if expecting to see the Watcher standing right there. \n");
                        dialog.AddOption("I Will Hunt Him Down", 12);
                        dialog.AddOption("Need some time to think", 255);
                        dialog.AddAvatar(63);
                        dialog.FinalizeDialog();
                        break;
                    }

            }
        }
        [Npc(NpcID.EventsGuide)]
        public static void EventsGuide(Client.GameClient client, ServerSockets.Packet stream, byte Option, string Input, uint id)
        {
            Dialog dialog = new Dialog(client, stream);
