        [Npc(NpcID.HeroOfGame)]
        public static void HeroOfGame(Client.GameClient client, ServerSockets.Packet stream, byte Option, string Input, uint id)
        {
            Dialog dialog = new Dialog(client, stream);
            TournamentType Type = TournamentType.None;
            switch (Option)
            {
                case 0:
                    {
                        dialog.AddText("Hey there " + client.Player.Name + " im Tournament Steward choose what would you like to Join?");

                        foreach (ITournament tournament in MsgSchedules.Tournaments.Values)
                        {
                            switch (tournament.Process)
                            {

                                case ProcesType.Dead:
                                    {
                                        if (tournament.Type == TournamentType.HeroOfGame)
                                            dialog.AddOption(tournament.Type.ToString() + " (" + tournament.Process.ToString() + ")", 104);

                                        break;
                                    }
                                case ProcesType.Idle:
                                case ProcesType.Alive:
                                    {
                                        dialog.AddOption(tournament.Type.ToString() + " (" + tournament.Process.ToString() + ")", (byte)tournament.Type);
                                        break;
                                    }
                            }
                        }
                        dialog.AddOption("I will come later. ", 255);
                        dialog.AddAvatar(63);
                        dialog.FinalizeDialog();
                        break;
                    }
                case 104:
                    {
                        dialog.AddText("Glad to see you! I take it that you haven`t heard of the Hero Of Game tournament? please allow me to introduce this exciting event for you.");
                        dialog.AddText("It`s a Pk Tournament that takes place DayOfWeek xx: 35 !");
                        dialog.AddOption("I will come later. ", 255);
                        dialog.AddAvatar(63);
                        dialog.FinalizeDialog();
                        break;
                    }
            }
            Type = (TournamentType)Option;
            switch (Type)
            {
                case Game.MsgTournaments.TournamentType.HeroOfGame:
                    {
                        if (Game.MsgTournaments.MsgSchedules.CurrentTournament.Type != Type || Game.MsgTournaments.MsgSchedules.CurrentTournament.Process != Game.MsgTournaments.ProcesType.Idle)
                        {
                            dialog.AddText("Glad to see you! I take it that you haven`t heard of the Hero Of Game tournament? please allow me to introduce this exciting event for you.");
                            dialog.AddText("It`s a Pk Tournament that takes place during on 40 minutes !");
                            dialog.AddOption("I will come later. ", 255);
                            dialog.AddAvatar(63).FinalizeDialog(false);
                            return;
                        }
                        if (!Game.MsgTournaments.MsgSchedules.CurrentTournament.Join(client, stream))
                        {
                            dialog.AddText(string.Concat(new string[] { "Hey ", client.Player.Name, ",", Type.ToString(), " not running at the moment, come back later" }));
                            dialog.AddOption("I see. ", 255);
                            dialog.AddAvatar(63).FinalizeDialog(false);
                            return;
                        }
                        break;
                    }
            }
        }

