        [NpcAttribute(NpcID.FrostToken)]
        public static void FrostToken(Client.GameClient client, ServerSockets.Packet stream, byte Option, string Input, uint id)
        {
            Dialog data = new Dialog(client, stream);
            switch (Option)
            {
                case 0:
                    {
                        data.AddText("--------------------------------------------------------------------------------------------------------\n");
                        data.AddText("Hello " + client.Player.Name + ", Welcome to [" + Program.ServerConfig.ServerName + " Server] I will be glad to tell yo about this Item.\n");
                        data.AddText("Frist of all you need [200] Online Point to use this item, when you finally active this item you can close your account or continue playing the game and you will get Conquer Points Every Minute.\n");
                        data.AddText("--------------------------------------------------------------------------------------------------------\n");
                        data.AddOption("1-Active the item [200 Online Point]",1);
                        data.AddOption("2-Renew The Item [5000 Online Point]",2);
                        data.AddOption("3-Check Time Left",3);
                        data.AddOption("4-Desactive",4);
                        data.AddOption("Need some time to think", 255);
                        data.AddAvatar(261).FinalizeDialog();
                        break;
                    }
                case 1:
                    {
                        if(client.Player.OnlineMinutes >= 200 && DeadRabbitProject.FrostToken.Activate.IsValid(client.Player.UID.ToString()))
                        {
                            client.Player.OnlineMinutes -= 200;
                            DeadRabbitProject.FrostToken.Activate.Active(client.Player.UID.ToString(), client.Player.Name);
                            data.AddText("--------------------------------------------------------------------------------------------------------\n");
                            data.AddText("Congratulations " + client.Player.Name + ", The FrostToken Is active Now.\n");
                            data.AddText("--------------------------------------------------------------------------------------------------------\n");
                            data.AddOption("1-Thanks", 255);
                            data.AddOption("3-Check Time Left", 3);
                            data.AddOption("2-Desactive", 4);
                            data.AddAvatar(261).FinalizeDialog();
                        }
                        else
                        {
                            data.AddText("Unfortunately dear " + client.Player.Name + ", you don't have enough Points To Activate The Frost Token, you have [" + client.MyNinja.Score + "] Point.\n");
                            data.AddOption("My Bad", 255);
                            data.AddAvatar(261).FinalizeDialog();
                        }
                        break;
                    }
            }
        }
