                                else data.AddOption(Database.HWRank.GetIndex((Database.MagicType.WeaponsType)type).ToString() + " - " + weaponName + ".", (byte)(type - 400));  
                            }
                            data.Option("I will think about it", 255);
                            data.AddAvatar(261).FinalizeDialog();
                        }
                        else
                        {
                            data.AddText("Unfortunately dear " + client.Player.Name + ", you don't have enough Online Points, you have [" + client.Player.OnlineMinutes + "] Point.\n");
                            data.AddOption("My Bad", 255);
                            data.AddAvatar(261).FinalizeDialog();
                        }
                        break;
                    }
                default:
                    {
                        if (client.Player.OnlineMinutes >= 100)
                        {
                            client.Player.OnlineMinutes -= 100;
                            client.HundredWeapons.AddWeapon((Database.MagicType.WeaponsType)(Option + 400), 1, true);
                            data.AddText("<tip desc=People#has#forgotten#the#real#name#of#the#Li Xiaoyao,#");
                            data.AddText("but#still#remember#he#learned#arts#of#swords#on#Mount#Su.>Li Xiaoyao</tip>:\n");
                            data.AddText("    You have inspired " + ((Database.MagicType.WeaponsType)(Option + 400)).ToString() + "!\n");
                            data.AddOption("Thanks.", 255);
                            data.AddAvatar(261).FinalizeDialog();
                        }
                        else
                        {
                            data.AddText("Unfortunately dear " + client.Player.Name + ", you don't have enough Online Points, you have [" + client.Player.OnlineMinutes + "] Point.\n");
                            data.AddOption("My Bad", 255);
                            data.AddAvatar(261).FinalizeDialog();
                        }
                        break;
                    }
                #endregion
                case 2:
                    {
                        if(client.Player.OnlineMinutes >=500)
                        {
                            if (client.Player.Reborn == 2 && client.Player.Level >= 120 && !client.MyAstredge.Items.ContainsKey(Astredge.TypeID.Astredge))
                            {
                                client.Player.OnlineMinutes -= 500;
                                client.MyAstredge.AddItem(Astredge.TypeID.Astredge, 1);
                            }
                            else
                            {
                                data.AddText("Unfortunately dear " + client.Player.Name + ", You don't match the requerments to unlock the Astredge System.\n");
                                data.AddOption("My Bad", 255);
                                data.AddAvatar(261).FinalizeDialog();
                            }
                        
                        }
                        else
                        {
                            data.AddText("Unfortunately dear " + client.Player.Name + ", you don't have enough Online Points, you have [" + client.Player.OnlineMinutes + "] Point.\n");
                            data.AddOption("My Bad", 255);
                            data.AddAvatar(261).FinalizeDialog();
                        }
                        break;
                    }
            }
        }
        [NpcAttribute(NpcID.Translate)]
        public static void Translate(Client.GameClient client, ServerSockets.Packet stream, byte Option, string Input, uint id)
        {
            Dialog data = new Dialog(client, stream);
            switch (Option)
            {
                case 0:
                    {
                        data.AddText("Hello "+client.Player.Name+" i can change your npcs language if you want just select the language you want.");
                        data.AddText("Your current language is " + client.OnLogin.Language + ".");
                        if (client.OnLogin.Language == "en")
                        {
                            data.AddOption("Arabic [AR]", 1);
                        }
                        else
                        {
                            data.AddOption("English [EN]", 1);
                        }
                        data.AddOption("No Thanks", 255);
                        data.AddAvatar(183).FinalizeDialog();
                        break;
                    }
                case 1:
                    {
                        if (client.OnLogin.Language == "en")
                        {
                            client.OnLogin.Language = "ar";
                        }
                        else
                        {
                            client.OnLogin.Language = "en";
                        }
                        client.CreateBoxDialog("You have changes the language to "+  client.OnLogin.Language);
                        break;
                    }
            }
        }
        [NpcAttribute(NpcID.AllOpen)]
        public static void AllOpen(Client.GameClient client, ServerSockets.Packet stream, byte Option, string Input, uint id)
        {

            Dialog data = new Dialog(client, stream);
            switch (Option)
            {
                case 0:
                    {
                        data.Text("Can You unlock All Titles, Halos Or Wings for 500 Online Point do you want this service? \n");
                        data.Option("1-Unlock All Title [500] Online Point", 1);
                        data.Option("2-Unlock All Wings [500] Online Point", 2);
                        data.Option("3-Unlock All Halos [500] Online Point", 3);
                        data.Option("4-Unlock Random HairStyles [10k] Conquer Point", 4);
                        data.Option("I will Think About This", 255);
                       // data.Option("Unlock~All~Avatar", 4);
                        data.AddAvatar(261).FinalizeDialog();
                        break;

                    }
                case 1:
                    {
                        if(client.Player.OnlineMinutes >=500)
                        {
                            client.Player.OnlineMinutes -= 500;
                            client.Player.WarDropeFull = 2;
                            var Title = DeadRabbitProject.Database.TitleStorage.Titles.Values.Where(p => p.ID >= 1 && p.ID <= 4000).ToArray();
                            foreach (var info in Title)
                            {
                                if (!client.Player.SpecialTitles.Contains((MsgTitleStorage.TitleType)info.SubID))
                                {
                                    client.Player.AddSpecialTitle((Game.MsgServer.MsgTitleStorage.TitleType)info.SubID, stream);
                                }
                            }
                            data.Text("Congratulations,You have unlocked all the titles \n");
                            data.Option("Thanks", 99);
                            data.AddAvatar(261).FinalizeDialog();
                            
                        }
                        else
                        {
                            data.Text("Unfortunately,You don't have enough Online Points \n");
                            data.Option("My Bad", 99);
                            data.AddAvatar(261).FinalizeDialog();
                        }
                        break;
                    }
                case 2:
                    {
                        if(client.Player.OnlineMinutes >= 500)
                        {
                            client.Player.OnlineMinutes -= 500;
                            client.Player.WarDropeFull = 2;
                            var Wings = DeadRabbitProject.Database.TitleStorage.Wings.Values.Where(p => p.ID >= 4001 && p.ID <= 8000).ToArray();
                            foreach (var info in Wings)
                            {
                                if (!client.Player.WingsTitles.Contains((MsgTitleStorage.WingsType)info.SubID))
                                {
                                    client.Player.AddSpecialWings((Game.MsgServer.MsgTitleStorage.WingsType)info.SubID, stream);
                                }
                            }
                            data.Text("Congratulations,You have unlocked all the wings \n");
                            data.Option("Thanks", 99);
                            data.AddAvatar(261).FinalizeDialog();
                        }
                        else
                        {
                            data.Text("Unfortunately,You don't have enough Online Points \n");
                            data.Option("My Bad", 99);
                            data.AddAvatar(261).FinalizeDialog();
                        }
                        
                        break;
                    }
                case 3:
                    {
                        if(client.Player.OnlineMinutes >= 500)
                        {
                            client.Player.OnlineMinutes -= 500;
                            client.Player.OpenAllHalos = 1;
                            var Halo = DeadRabbitProject.Database.TitleStorage.Titles.Values.Where(p => p.SubID > 6074).ToArray();
                            foreach (var info in Halo)
                            {
                                if (!client.Player.HaloTitles.Contains((MsgTitleStorage.HaloType)info.SubID))
                                {
                                    client.Player.AddSpecialHalo((Game.MsgServer.MsgTitleStorage.HaloType)info.SubID, stream);
                                }
                            }
                            data.Text("Congratulations,You have unlocked all the Halos \n");
                            data.Option("Thanks", 99);
                            data.AddAvatar(261).FinalizeDialog();
                        }
                        else
                        {
                            data.Text("Unfortunately,You don't have enough Online Points \n");
                            data.Option("My Bad", 99);
                            data.AddAvatar(261).FinalizeDialog();
                        }
                       
                        break;
                    }
                case 4:
                    {
                        if (client.Player.ConquerPoints >= 10000)
                        {
                            while (true)
                            {
                                var vals = Database.HairfaceStorageTable.Hairfaces.Where(i => i.Type == MsgHairfaceStorage.Type.Hairstyle && client.HairfaceStorage.CanEquip(i) && !client.HairfaceStorage.Exists(i.ID, i.Type)).ToArray();
                                if (vals.Length > 0)
                                {
                                    var rand = (ushort)(Pool.GetRandom.Next() % 1000);
                                    int position = Pool.GetRandom.Next(0, vals.Length);

                                    if (client.HairfaceStorage.Add(vals[position]))
                                    {
                                        client.Player.ConquerPoints -= 10000;
                                        data.Text("Congratulations! You've got " + vals[position].Name + " HairStyle!");

                                        data.Option("Try another time.", 4);
                                        data.Option("Thanks.", 255).FinalizeDialog();
                                        break;
                                    }
                                }
                                else
                                {
                                    data.Text("You are not qualified to get any avatars.");

                                    data.Option("I~see.", 255).FinalizeDialog();
                                    break;
                                }
                            }
                        }
                        else
                        {
                            data.Text("Hey hey! you don't have the required amount of Conquer Points!");

                            data.Option("I~see.", 255).FinalizeDialog();
                        }
                        break;
                    }
            }
        }
