        #region prizeTops
        [NpcAttribute(NpcID.prizetop0)]
        public static void prizetop0(Client.GameClient client, ServerSockets.Packet stream, byte Option, string Input, uint id)
        {
            Dialog dialog = new Dialog(client, stream);
            switch (Option)
            {
                case 0:
                    {
                        dialog.Text("Hello Sir, i can teleport you to event.\n");

                        dialog.Option("Calim~Reward.", 1);

                        dialog.Option("I~see.", 255).FinalizeDialog();
                        break;
                    }
                case 1:
                    {
                        int alive = 0;
                        DateTime Now64 = DateTime.Now;
                        foreach (Client.GameClient Entitys in Pool.GamePoll.Values)
                            if (Entitys.Player.Map == 4447 && Entitys.Player.Alive)

                                alive++;
                        if (client.Player.ContainFlag(Game.MsgServer.MsgUpdate.Flags.Dead))
                        {
                            client.SendSysMesage(" you are dead now");
                            break;
                        }
                        if (Now64.Minute >= 5 && Now64.Minute <= 9)
                        {
                            if (alive == 1)
                            {
                                client.Player.ConquerPoints += NewSystem.SideTopPrize.SideTop; // 5m CPs <<
                                client.Player.Money += NewSystem.SideTopPrize.SideTopMoney; // 50m Gold <<<
                                Random random = new Random();
                                int GiftID = random.Next(0, NewSystem.SideTopPrize.Gift.Length);
                                uint ItemID = NewSystem.SideTopPrize.Gift[GiftID];
                                client.Inventory.Add(stream, ItemID); // Rune Yellow BossKiller +2 <<
                                Game.MsgTournaments.MsgSchedules.SendSysMesage(client.Player.Name + " has Won and rewarded " + NewSystem.SideTopPrize.SideTop + " CPs, " + NewSystem.SideTopPrize.SideTopMoney + " Money, Random Gift", MsgMessage.ChatMode.Center);
                                client.Teleport(1002, 410, 354);
                                {
                                    if (client.Player.Map == 4447)
                                    {
                                        client.Teleport(1002, 410, 354);

                                    }
                                }
                            }
                            else
                            {
                                dialog.AddText("There are still " + alive + " Entitys in the map kill it first to claim prize!");
                                dialog.AddOption("okay", 255).AddAvatar(80).FinalizeDialog();

                                break;
                            }
                        }
                        else
                        {
                            dialog.AddText("Hey there " + client.Player.Name + "You can only claim the prize when the time on  xx5");
                            dialog.AddOption("okay", 255).AddAvatar(80).FinalizeDialog();

                            break;
                        }
                        break;
                    }

            }
        }

