        [NpcAttribute(NpcID.ArchivesArcher)]
        public static void ArchivesArcher(Client.GameClient client, ServerSockets.Packet stream, byte Option, string Input, uint id)
        {
            Dialog data = new Dialog(client, stream);
            switch (Option)
            {
                case 0:
                    {

                        data.Text("Hello Dear "+client.Player.Name+", Do You Want to Unlock Your Archive?");
                        data.Option("StoneCracker [500] Online Point ", 1);
                        data.Option("ColdMoon [500] Online Point", 2);
                        data.Option("ThornCutter [500] Online Point", 3);
                        data.Option("I will think about it", 255);
                        data.AddAvatar(118).FinalizeDialog();
                        return;
                    }
                case 1:
                    {
                        if (client.Player.OnlineMinutes >= 500 && client.Player.ArcherArchives == 0)
                        {
                            client.Player.OnlineMinutes -= 500;
                            client.MyArchives.AddItem(Archives.TypeID.StoneCracker, 1, 0, 1, 0);
                            client.Player.ArcherArchives += 1;
                        }
                        else
                        {
                            data.Text("Unfortunately,you don't have enough Points");
                            data.Option("i,See!", 255);
                            data.AddAvatar(118).FinalizeDialog();
                        }
                        break;
                    }
                case 2:
                    {
                        if (client.Player.OnlineMinutes >= 500 && client.Player.ArcherArchives == 1)
                        {
                            client.Player.OnlineMinutes -= 500;
                            client.MyArchives.AddItem(Archives.TypeID.ColdMoon, 1, 0, 0, 0);
                            client.Player.ArcherArchives += 1;
                        }
                        else
                        {
                            data.Text("Unfortunately,you don't have enough Points");
                            data.Option("i,See!", 255);
                            data.AddAvatar(118).FinalizeDialog();
                        }
                        break;
                    }
                case 3:
                    {
                        if (client.Player.OnlineMinutes >= 500 && client.Player.ArcherArchives == 2)
                        {
                            client.Player.OnlineMinutes -= 500;
                            client.MyArchives.AddItem(Archives.TypeID.ThornCutter, 1, 0, 0, 0);
                            client.Player.ArcherArchives += 1;
                        }
                        else
                        {
                            data.Text("Unfortunately,you don't have enough Points");
                            data.Option("i,See!", 255);
                            data.AddAvatar(118).FinalizeDialog();
                        }
                        break;
                    }
            }
        }

