        [NpcAttribute(NpcID.ArchivesNinja)]
        public static void ArchivesNinja(Client.GameClient client, ServerSockets.Packet stream, byte Option, string Input, uint id)
        {
            Dialog data = new Dialog(client, stream);
            switch (Option)
            {
                case 0:
                    {
                        data.AddText("Hello, How can i help you today sir ? .");
                        data.AddOption("Please UnLock My Archive Ninja [500] Online Point", 1);
                        data.AddOption("Please UnLock New My Archive Ninja [2000] Online Point", 2);
                        data.AddOption("I`ll~think~about~it .");
                        data.AddAvatar(263).FinalizeDialog();
                        break;


                    }
                case 2:
                    {
                        if (client.MyNinja.Score >= 60000)
                        {
                            if (client.Player.OnlineMinutes >= 2000)
                            {
                                client.Player.OnlineMinutes -= 2000;
                                if (Database.AtributesStatus.IsNinja(client.Player.Class))
                                {

                                    client.MyNinja.SusanooLevel = 1;
                                    MsgGouYuAptitude.MsgGouYuAptitudeProto.Create(client, client.MyNinja, client.Player.UID, MsgGouYuAptitude.MsgGouYuAptitudeProto.TypeID.UnlockSusanoo);
                                    client.Player.SendString(stream, MsgStringPacket.StringID.Effect, id, true, "firemagic");
                                }
                            }
                            else
                            {
                                data.Text("Unfortunately, You don't have 2000 Online Point to unlock Ninja Archive");
                                data.Option("I~See.", 255).FinalizeDialog();
                            }
                        }
                        else
                        {
                            data.Text("Come When You Have Score 60000");
                            data.Option("I~See.", 255).FinalizeDialog();
                        }
                        break;

                    }
                case 1:
                    {
                        if (client.Player.OnlineMinutes >= 500)
                        {
                            client.Player.OnlineMinutes -= 500;
                            if (Database.AtributesStatus.IsNinja(client.Player.Class))
                            {
                                MsgMessage.NpcCommands(client, new Game.MsgServer.MsgMessage("@open_ninja", 0, 0));
                                client.Player.SendString(stream, MsgStringPacket.StringID.Effect, id, true, "firemagic");
                            }
                        }
                        else
                        {
                            data.Text("Unfortunately,You don't have 500 Online Point to unlock Ninja Archive");

                            data.Option("I~See.", 255).FinalizeDialog();
                        }
                        break;

                    }
            }
        }

