        [NpcAttribute(NpcID.OpenArchives)]
        public static void OpenArchives(Client.GameClient client, ServerSockets.Packet stream, byte Option, string Input, uint id)
        {
            Dialog data = new Dialog(client, stream);


            switch (Option)
            {
                case 0:
                    {
                        if (!client.HundredWeapons.Valid())
                        {
                            data.AddText("<tip desc=People#has#forgotten#the#real#name#of#the#Li Xiaoyao,#");
                            data.AddText("but#still#remember#he#learned#arts#of#swords#on#Mount#Su.>Li Xiaoyao</tip>:\n");
                            data.AddText("    You have to be a trojan level 40 and promoted once at least to unlock Weapon Archive.\n");
                            data.AddOption("I~see.", 255);
                        }
                        else if (!client.HundredWeapons.Unlocked)
                        {
                            data.AddText("<tip desc=People#has#forgotten#the#real#name#of#the#Li Xiaoyao,#");
                            data.AddText("but#still#remember#he#learned#arts#of#swords#on#Mount#Su.>Li Xiaoyao</tip>:\n");
                            data.AddText("Hello Dear "+client.Player.Name+", Do you want to unlock Weapon Archive for 500 Online Point?\n");
                            data.AddOption("Yes~please.", 254);
                            data.AddOption("I~see.", 255);
                        }
                        else
                        {
                            data.AddText("<tip desc=People#has#forgotten#the#real#name#of#the#Li Xiaoyao,#");
                            data.AddText("but#still#remember#he#learned#arts#of#swords#on#Mount#Su.>Li Xiaoyao</tip>:\n");
                            data.AddText("    Please select the Weapon You Want To inspire its spirit. It costs 100,000 Conquer Points.\n");
                            for (byte i = 1; i <= 9; i++)
                            {
                                ushort type = (ushort)(400 + i * 10);
                                if (type == 470)
                                    type = 481;
                                string weaponName = ((Database.MagicType.WeaponsType)type).ToString();
                                if (client.HundredWeapons.ContainsWeapon((Database.MagicType.WeaponsType)type))
                                    data.AddOption(Database.HWRank.GetIndex((Database.MagicType.WeaponsType)type).ToString() + " - " + weaponName + "[Inspired].", 255);
                                else data.AddOption(Database.HWRank.GetIndex((Database.MagicType.WeaponsType)type).ToString() + " - " + weaponName + ".", (byte)(type - 400));
                            }
                        }
                        data.FinalizeDialog();
                        break;
                    }
                default:
                    {
                        if (client.Player.ConquerPoints >= 100000)
                        {
                            client.Player.ConquerPoints -= 100000;
                            client.HundredWeapons.AddWeapon((Database.MagicType.WeaponsType)(Option + 400), 1, true);
                            data.AddText("<tip desc=People#has#forgotten#the#real#name#of#the#Li Xiaoyao,#");
                            data.AddText("but#still#remember#he#learned#arts#of#swords#on#Mount#Su.>Li Xiaoyao</tip>:\n");
                            data.AddText("    You have inspired " + ((Database.MagicType.WeaponsType)(Option + 400)).ToString() + "!\n");
                            data.AddOption("Thanks.", 255);
                        }
                        else
                        {
                            data.AddText("<tip desc=People#has#forgotten#the#real#name#of#the#Li Xiaoyao,#");
                            data.AddText("but#still#remember#he#learned#arts#of#swords#on#Mount#Su.>Li Xiaoyao</tip>:\n");
                            data.AddText("    You don't have 10,000 Conquer Points in your inventory!\n");
                            data.AddOption("My~bad.", 255);
                        }
                        data.FinalizeDialog();
                        break;
                    }
                case 254:
                    {
                        if (client.HundredWeapons.Valid())
                        {
                            if(client.Player.OnlineMinutes >=500)
                            {
                                client.Player.OnlineMinutes -= 500;
                                client.HundredWeapons.Unlocked = true;
                                client.Send(stream.CreateHundredWeaponsInfo(client, MsgHundredWeaponsInfo.ActionID.RequestInfo));
                                client.Send(stream.ActionCreate(new ActionQuery() { Type = ActionType.OpenDialog, ObjId = client.Player.UID, Timestamp = (uint)Time32.timeGetTime().GetHashCode(), dwParam = DialogCommands.TrojanWeaponArchive, PositionX = client.Player.X, PositionY = client.Player.Y }));

                                data.AddText("<tip desc=People#has#forgotten#the#real#name#of#the#Li Xiaoyao,#");
                                data.AddText("but#still#remember#he#learned#arts#of#swords#on#Mount#Su.>Li Xiaoyao</tip>:\n");
                                data.AddText("    You have unlocked Weapon Archive!\n");
                                data.AddOption("Thanks.", 255);
                                data.FinalizeDialog();
                            }
                            else
                            {
                                data.AddText("Unfortunately, You don't have enough online points");
                                data.AddOption("My Bad.", 255);
                                data.FinalizeDialog();
                            }
                            
                        }
                        break;
                    }

            }
        }
        [NpcAttribute(NpcID.SwordMaster)]
        public static void SwordMaster(Client.GameClient client, ServerSockets.Packet stream, byte Option, string Input, uint id)
        {
            Dialog data = new Dialog(client, stream);


            switch (Option)
            {
                case 0:
                    {
                        data.AddText("<tip desc=People#has#forgotten#the#real#name#of#the#Swordmaster,#")
                                 .AddText("but#still#remember#he#learned#arts#of#swords#on#Mount#Su.>Swordmaster</tip>:\n")
                                 .AddText("    You must have heard that Weapon Archives will spark stunning inspirations.\n")
                                 .AddText("    Guardian space is most impressive inspiration. Now you can enter Weapon Archives and preview diversified Guardian status.\n")
                                  .AddOption("View~Guardian~status.", 1).FinalizeDialog();
                        break;
                    }
                case 1:
                    {
                        if (client.HundredWeapons.Valid() && client.HundredWeapons.Unlocked && client.HundredWeapons.Objects.Values.Count(i => i.Level > 3) > 0)
                        {
                            client.Send(stream.ActionCreate(new ActionQuery() { Type = ActionType.OpenDialog, ObjId = client.Player.UID, Timestamp = (uint)Time32.timeGetTime().GetHashCode(), dwParam = DialogCommands.TrojanWeaponArchiveLook, PositionX = client.Player.X, PositionY = client.Player.Y }));
                        }
                        else
                        {
                            data.AddText("    This Guardian space can be opened only when you have a Weapon Spirit of 3-star or above.\n")
                                .AddText("    If you`re a Trojan reaching Lv.40, you can go find Mr. Pride in the Dragland to unlock Weapon Archives system.")
                                 .AddOption("I~see.", 255).FinalizeDialog();
                            break;
                        }
                        break;
                    }
            }
        }


        [NpcAttribute(NpcID.SecurityAnima)]
        public static void SecurityAnima(Client.GameClient client, ServerSockets.Packet stream, byte Option, string Input, uint id)
        {

            Dialog dialog = new Dialog(client, stream);
            switch (Option)
            {
                case 0:
                    {
                        dialog.Text("Hi , From here you can protect your Anima , you can activate your own security code.\n");
                        dialog.Text("Actived = " + client.Player.TREPIN2 + "");
                        dialog.AddOption("Create Security Code", 1);
                        dialog.AddOption("Change Password", 10);
                        dialog.AddOption("Forget Password", 5);
                        dialog.AddOption("Remove Password", 50);
                        dialog.AddOption("Actived Password", 81);
                        dialog.AddOption("I~see.");
                        dialog.Avatar(286).FinalizeDialog();

                        break;
                    }
                #region Create New PinCode
                case 1:
                    {
                        dialog.Text("Create New PinCode");
                        dialog.AddInput("Write:", 2, 6);
                        dialog.Avatar(286).FinalizeDialog();
                        break;
                    }
                case 2:
                    {
                        string pin = Input, PINQ = "";
                        if (pin.Length != 6)
                        {
                            client.Player.MessageBox("Input 6 Number Or Letters", null, null, 60);
                            goto case 0;
                        }
                        string Get3Numper = pin.Substring(3);
                        for (int x = 0; x < pin.Length - Get3Numper.Length; x++)
                            PINQ += "*";
                        PINQ += Get3Numper;
                        client.Player.OrginalInput2 = Input;
                        dialog.Text("This The is PinCode?." + PINQ);
                        dialog.Option("Are you sure to write this Pin Code? ", 3);
                        dialog.Avatar(286).FinalizeDialog();

                        break;
                    }
                case 3:
                    {
                        string pin = client.Player.OrginalInput2;
                        if (client.Player.PinCodeAnima.ToLower() == "" && pin.Length == 6 && pin != "")
                        {
                            client.Player.PinCodeAnima = pin.ToLower();
                            client.Player.MessageBox("Done " + pin + "", null, null, 60);
                        }
                        else
                            goto case 0;
                        dialog.Avatar(286).FinalizeDialog();
                        break;
                    }
                #endregion
                #region Change PinCode
                case 10:
                    {

                        dialog.AddText("Please input your old PinCode.")
                            .AddInput("Old PinCode: ", 11, 6)
                            .AddOption("Just passing by.", 20)
                            .FinalizeDialog();
                        break;

                    }
                case 12:
                    {

                        dialog.Text("This The is Old PinCode?." + client.Player.OrginalInput2);
                        dialog.Text(" If correct, write the new PinCode.");
                        dialog.AddInput("EnterNew ", 13, 6);
                        dialog.Avatar(286).FinalizeDialog();
                        break;

                    }
                case 13:
                    {

                        if (Input.Length == 6)
                        {
                            client.Player.PinCodeAnima = Input.ToLower();
                            //client.Player.TREPIN = true;
                            client.Player.MessageBox("Done Chanage", null, null, 60);
                            goto case 0;
                        }
                        else
                        {
                            client.Player.MessageBox("Please Input 6 Number Or Letters", null, null, 60);
                            goto case 0;
                        }
                    }
                case 11:
                    {
                        string pin = Input, PINQ = "";
                        if (pin.Length != 6)
                        {
                            client.Player.MessageBox("Input 6 Number Or Letters", null, null, 60);
                            goto case 10;
                        }
                        string Get3Numper = pin.Substring(3);
                        for (int x = 0; x < pin.Length - Get3Numper.Length; x++)
                            PINQ += "*";
                        PINQ += Get3Numper;
                        client.Player.OrginalInput2 = PINQ;

                        if (pin.Length == 6 && client.Player.PinCodeAnima.ToLower() == pin.ToLower())
                        {
                            goto case 12;
                        }
                        else
                        {
                            client.Player.MessageBox("Old PinCode incorrect", null, null, 60);
                            goto case 0;
                        }


                    }
                #endregion
                #region Forget PinCode
                case 5:
                    {
                        dialog.AddText("Please input your email .. @yahoo.Com will input automatic.")
                            .AddInput("Yahoo: ", 6)
                            .AddOption("Just passing by.")
                            .FinalizeDialog();
                        break;
                    }
                case 6:
                    {
                        if (Input != "")
                        {
                            string mail = Input.Contains("@") ? "" : "@yahoo.com";
                            client.ChangePassword.Email = Input + mail;
                            bool exist = false;
                            using (var cmd = new DBFunctionality.MySqlCommand(DBFunctionality.MySqlCommandType.SELECT).Select("accounts").Where("ID", client.Player.UID).And("Email", client.ChangePassword.Email))
                            using (var reader = new DBFunctionality.MySqlReader(cmd))
                            {
                                if (reader.Read())
                                {
                                    exist = true;
                                }
                            }
                            if (exist)
                            {
                                dialog.AddText("Your PinCode [ " + client.Player.PinCodeAnima + " ]");
                                dialog.AddOption("Just passing by.");
                                dialog.Avatar(86).FinalizeDialog();
                                // goto case 0;
                            }
                            else
                            {
                                dialog.AddText("Please input your data again.");
                                dialog.AddOption("Alrihgt.");
                                dialog.Avatar(86).FinalizeDialog();
                                // goto case 5;
                            }
                        }
                        break;
                    }
                #endregion
                #region RemovePinCode
                case 50:
                    {
                        dialog.AddText("Please input your email .. @yahoo.Com will input automatic.")
                            .AddInput("Yahoo: ", 60)
                            .AddOption("Just passing by.")
                            .FinalizeDialog();
                        break;
                    }
                case 60:
                    {
                        if (Input != "")
                        {
                            string mail = Input.Contains("@") ? "" : "@yahoo.com";
                            client.ChangePassword.Email = Input + mail;
                            bool exist = false;
                            using (var cmd = new DBFunctionality.MySqlCommand(DBFunctionality.MySqlCommandType.SELECT).Select("accounts").Where("ID", client.Player.UID).And("Email", client.ChangePassword.Email))
                            using (var reader = new DBFunctionality.MySqlReader(cmd))
                            {
                                if (reader.Read())
                                {
                                    exist = true;
                                }
                            }
                            if (exist)
                            {
                                dialog.AddText("Done Remove PinCode");
                                dialog.AddOption("Just passing by.", 20);
                                dialog.Avatar(86).FinalizeDialog();
                                client.Player.PinCodeAnima = "";
                                client.Player.TREPIN2 = false;
                                // goto case 0;
                            }
                            else
                            {
                                dialog.AddText("Please input your data again.");
                                dialog.AddOption("Alrihgt.", 5);
                                dialog.Avatar(86).FinalizeDialog();
                                // goto case 5;
                            }
                        }
                        break;
                    }
                #endregion
                #region Actived Password
                case 81:
                    {
                        dialog.AddText("Please input your old PinCode.")
                           .AddInput("InterPassword: ", 80, 6)
                           .AddOption("Just passing by.", 20)
                           .FinalizeDialog();
                        break;
                    }
                case 80:
                    {
                        string pin = Input;
                        if (pin.Length != 6)
                        {
                            client.Player.MessageBox("Input 6 Number Or Letters", null, null, 60);
                            goto case 0;
                        }
                        if (pin.Length == 6 && client.Player.PinCodeAnima.ToLower() == pin.ToLower())
                        {
                            client.Player.TREPIN2 = true;
                            client.Player.MessageBox("The account has been activated", null, null, 60);
                        }
                        else
                            goto case 0;
                        break;
                    }
                #endregion
            }
        }


