        [NpcAttribute(NpcID.HosuuNpcs)]
        public static void HosuuNpcs(Client.GameClient client, ServerSockets.Packet stream, byte Option, string Input, uint id)
        {
            Dialog data = new Dialog(client, stream);
            switch (Option)
            {
                case 0:
                    {
                        data.AddText("Hi, i master your hossu's perfection level for 600,000 CPs.\nDo you wanna?");
                        data.AddOption("Yes Please.", 1);
                        data.AddOption("Just passing by..");
                        data.AddAvatar(260).FinalizeDialog();
                        break;
                    }
                case 1:
                    {
                        if (client.Player.ConquerPoints >= 600000)
                        {
                            if (client.Inventory.HaveSpace(1))
                            {
                                MsgGameItem gameDB;
                                if (client.Equipment.TryGetEquip(Role.Flags.ConquerItem.LeftWeapon, out gameDB))
                                {
                                    if (Database.ItemType.IsShield(gameDB.ITEM_ID))
                                    {
                                        if (gameDB.PerfectionLevel != 54)
                                        {
                                            gameDB.PerfectionLevel = 54;
                                            gameDB.PerfectionProgress = 0;
                                            gameDB.OwnerName = client.Player.Name;
                                            gameDB.OwnerName = client.Player.Name;
                                            gameDB.OwnerUID = client.Player.UID;

                                            gameDB.Mode = Role.Flags.ItemMode.Update;
                                            gameDB.Send(client, stream);

                                            client.UpdatePerfectionLevel(stream);
                                            client.Equipment.QueryEquipment(client.Equipment.Alternante, true);

                                            client.Player.ConquerPoints -= 600000;
                                            client.Player.MessageBox("You have payed 600K cps and your Hossu now is perfection level 54.");
                                        }
                                    }
                                    else client.Player.MessageBox("Your left weapon is not a Hossu.");
                                }
                                else client.Player.MessageBox("Please equip your Hossu at first.");
                            }
                            else client.Player.MessageBox("Your inventory is full, Please remove some spots.");
                        }
                        else client.Player.MessageBox("You dont have 600K cps.");
                        break;
                    }
            }
        }
        [NpcAttribute(NpcID.BestFighter)]
        public static void BestFighter(Client.GameClient client, ServerSockets.Packet stream, byte Option, string Input, uint id)
        {
            Dialog data = new Dialog(client, stream);
            switch (Option)
            {
                case 0:
                    {
                        data.AddText("Hi, I'm the leader of BestFighter .. How can i help you?");
                        //if()
                        data.AddOption("Join Now", 1);
                        // data.AddOption("Reward.", 2);
                        data.AddOption("Just passing by..");
                        data.AddAvatar(263).FinalizeDialog();
                        break;
                    }
                case 1:
                    {
                        client.Player.SetLocationType = 3;
                        MsgInterServer.PipeClient.Connect(client, Database.GroupServerList.InterServer.IPAddress, Database.GroupServerList.InterServer.Port);
                        break;
                    }
            }
        }
    
      
        [NpcAttribute(NpcID.clearinventory)]
        public static void clearinventory(Client.GameClient client, ServerSockets.Packet stream, byte Option, string Input, uint id)
        {
            Dialog data = new Dialog(client, stream);
            switch (Option)
            {

                case 0:
                    {
                        data.AddText("I clear Your Item")
                                        .AddOption("Clearinventory", 1)
                           .AddOption("No.", 255).AddAvatar(277).FinalizeDialog();
                        break;
                    }
                case 1:
                    {
                        data.AddText("I clear Your Item").AddOption("Ok", 5).AddAvatar(277).FinalizeDialog();
                        break;
                    }
                case 5:
                    {
                        using (var r = new ServerSockets.RecycledPacket())
                            client.Inventory.ClearAll(r.GetStream());
                        break;
                    }


            }
        }
      
        [NpcAttribute(NpcID.ChangeToken)]
        public static void ChangeToken(Client.GameClient client, ServerSockets.Packet stream, byte Option, string Input, uint id)
        {
            Dialog data = new Dialog(client, stream);
            switch (Option)
            {
                case 0:
                    {
                        data.AddText("You~Can~Change~GoldPrize~For~This~Item ")
                      .AddOption("Change~GoldPrize", 1)
                        .AddAvatar(288)

                       .FinalizeDialog();
                        break;
                    }
                case 1:
                    {
                        if (client.Inventory.Contain(3001304, 1, 0))
                        {
                            client.Inventory.Remove(3001304, 1, stream);
                            if (client.Inventory.Contain(2100075, 1, 0))
                            {
                                client.Inventory.Remove(2100075, 1, stream);

                                client.Inventory.Add(stream, 2100095, 1);
                            }
                        }
                        else
                        {
                            data.AddText("You~Dont~Have~GoldPrize");
                            data.AddOption("Just passing by..");
                            data.AddAvatar(263).FinalizeDialog();
                        }
                        break;
                    }

            }
        }
