        [NpcAttribute(NpcID.RewardPoints)]
        public static void RewardPoints(Client.GameClient client, ServerSockets.Packet stream, byte Option, string Input, uint id)
        {
            Dialog data = new Dialog(client, stream);
            switch (Option)
            {
                case 0:
                    {
                        data.AddText("Hi, I'm the  I am Replace points representative , do you want anything ?\n");
                        data.AddText("Your " + client.Player.RewardPoints + " Points\n");
                        data.AddOption("MysteryFruit[1points]", 1);
                        data.AddOption("VIP6 1Hours [10points]", 2);
                        data.AddOption("LifeFruitBaske[5points]", 3);
                        data.AddOption("Just passing by..");
                        data.AddAvatar(263).FinalizeDialog();
                        break;
                    }
                #region RewardPoints
                case 1:
                    {
                        if (!client.Inventory.HaveSpace(1))
                        {
                            client.CreateBoxDialog("Please make 1 more space in your inventory.");
                            break;
                        }
                        if (client.Player.RewardPoints >= 1)
                        {
                            client.Player.RewardPoints -= 1;
                            client.Inventory.Add(stream, 3001044, 1);
                        }
                        else
                        {

                            data.AddText("Please take 1 Points .")
                            .AddOption("Thanks!", 255)
                            .AddAvatar(166).FinalizeDialog();

                        }
                        break;
                    }
                case 2:
                    {
                        if (!client.Inventory.HaveSpace(1))
                        {
                            client.CreateBoxDialog("Please make 1 more space in your inventory.");
                            break;
                        }
                        if (client.Player.RewardPoints >= 10)
                        {
                            client.Player.RewardPoints -= 10;
                            if (DateTime.Now > client.Player.ExpireVip)
                                client.Player.ExpireVip = DateTime.Now.AddHours(1);
                            else
                                client.Player.ExpireVip = client.Player.ExpireVip.AddHours(1);

                            client.Player.VipLevel = 6;

                            client.Player.SendUpdate(stream, client.Player.VipLevel, MsgUpdate.DataType.VIPLevel);

                            client.Player.UpdateVip(stream);

