        [NpcAttribute(NpcID.FullInnerPower)]
        public static void FullInnerPower(Client.GameClient client, ServerSockets.Packet stream, byte Option, string Input, uint id)
        {
            Dialog data = new Dialog(client, stream);
            switch (Option)
            {
                case 0:
                    {
                        data.AddText("Hello Dear "+client.Player.Name+", would you like to complete your InnerPower for 1000 Online Point ?\n");
                        data.AddOption("Full InnerPower [1000]", 1);
                        data.AddOption("Full Atributes Points [500]", 1);
                        data.AddOption("I want some time to think");
                        data.AddAvatar(263).FinalizeDialog();
                        break;
                    }
                case 1:
                    {
                        if(client.Player.OnlineMinutes >= 1000)
                        {
                            client.Player.OnlineMinutes -= 1000;
                            foreach (var m_stage in client.Player.InnerPower.Stages)
                            {
                                foreach (var m_gong in m_stage.NeiGongs)
                                {
                                    m_stage.UnLocked = m_gong.Unlocked = true;
                                    m_gong.Score = 100;
                                    Database.InnerPowerTable.Stage DBStage = null;
                                    Database.InnerPowerTable.Stage.NeiGong DBGong = null;
                                    if (Database.InnerPowerTable.GetDBInfo(m_gong.ID, out DBStage, out DBGong))
                                        m_gong.level = DBGong.MaxLevel;
                                }
                            }
                            client.Send(new MsgMessage("Congratulations", client.Player.Name, "Has fixed his [InnerPower]  Enjoy With [ Deadrabbit[EU] ]", 3).GetArray(stream));
                            //MsgSchedules.SendSysMesage("Congratulations ! [ " + client.Player.Name + " ] Has fixed his [InnerPower]  Enjoy With [ Deadrabbit[EU] ] !.", MsgServer.MsgMessage.ChatMode.Talk, MsgServer.MsgMessage.MsgColor.white);
                        }
                        else
                        {
                            data.AddText("Sorry, you don't have enough Online Point to complete the Task \n");
                            data.AddOption("My Bad");
                            data.AddAvatar(263).FinalizeDialog();
                            break;
                        }
                       
                        break;
                    }
            }
        }

