                        client.Player.QuestGUI.IncreaseQuestObjectives(stream, ActiveQuest.MissionId, 1);
                        data.AddText("It`s~a~DeadRabbitProject~bird~of~enormous~size~and~strength.~Though~I`ve~figured~out~the~way~of~making~the~Tempest~Wings,");
