        public static int GetMapEpicTrojanPoints(uint MapID)
        {
            if (MapID == 3826)
                return 150;
            if (MapID == 3827)
                return 200;
            if (MapID == 3828)
                return 250;
            if (MapID == 3829)
                return 300;
            return 0;
        }


