                                {
                                    Server.AddMapMonster(stream, p.Map, 7487, p.Player.X, p.Player.Y, 3, 3, 1, p.Player.DynamicID, false, MsgFloorItem.MsgItemPacket.EffectMonsters.None, "SuperXp-4");
