                        .AddOption("MapHunt[9].", 8)
                        .AddOption("MapHunt[10].", 9)
                        //.AddOption("MapHunt[BigMap].", 14)
                        .AddOption("#Thnx .", 255).AddAvatar(10).FinalizeDialog();
