                                    case 5: client.Teleport(47, 47, 22388); break; //MapHunt 7
                                    case 6: client.Teleport(47, 47, 22383); break; //MapHunt 3
                                    case 7: client.Teleport(47, 47, 22380); break; //MapHunt 8
                                    case 8: client.Teleport(47, 47, 22381); break; //MapHunt 9
                                    case 9: client.Teleport(47, 47, 22386); break; //MapHunt 10
                                    case 13: client.Teleport(47, 47, 22387); break; //MapHunt 4
                                    //case 14: client.Teleport(381, 271, 3846); break; //BigMapHunt
                                }//
                            }
                            else
                            {
                                data.AddText("Hey! You don't have 100 gold do you?\nDon't you dare try to cheat me or I'll call the guards!")
                             .AddOption("Crazy!", 255)
                             .AddAvatar(10)
                             .FinalizeDialog();
