        [NpcAttribute(NpcID.WinCrazyWar)]
        public static void Win(Client.GameClient client, ServerSockets.Packet stream, byte Option, string Input, uint id)
        {
            Dialog data = new Dialog(client, stream);
            switch (Option)
            {
                case 0:
                    {
                        data.AddText("Hey there " + client.Player.Name + " Would you like to Claim Your Prize?.")
                                .AddOption("Give~Me~My~Prize", 26)
                                 .AddOption("Tc", 2)
                        .AddOption("#Thnx .", 255)
                        .AddAvatar(63).FinalizeDialog();
                        break;
                    }
                case 26:
                    {
                        DateTime Now64 = DateTime.Now;
                        int alive = 0;
                        foreach (Client.GameClient Entitys in Pool.GamePoll.Values)
                            if (Entitys.Player.Map == 5661 && Entitys.Player.Alive && client.Player.HitPoints >= 1) alive++;
                        if (Now64.Minute >= 05 && Now64.Minute <= 59)
                        {
                            if (alive == 1)
                            {
                                client.Player.ConquerPoints += 250000;
                                //client.Inventory.Add100(3000848, 0, 1, stream);
                                string logs = "[High Cps]" + client.Player.Name + " get " + 250000 + " From SmallTops he have " + client.Player.ConquerPoints + "";
                                Database.ServerDatabase.LoginQueue.Enqueue(logs);
                                MsgSchedules.SendSysMesage(" Congratulations " + client.Player.Name + " claimed the prize " + 250000 + " Cps for winning the LastManStand  .", MsgServer.MsgMessage.ChatMode.Center, Game.MsgServer.MsgMessage.MsgColor.red);
                                client.Teleport(410, 354, 1002);
                            }
                            else
                            {
                                data.AddText("There are still " + alive + " Players in the map kill it first to claim prize!")
                                .AddOption("okay", 255)
                                    .AddAvatar(80)
                                    .FinalizeDialog();

                            }
                        }
                        else
                        {
                            data.AddText("Top End in xx:05 ")
                                .AddOption("Thanks", 58)
                                .AddAvatar(63).FinalizeDialog();
                        }
                        break;
                    }
                case 2:
                    {
                        client.Teleport(410, 354, 1002);
                        break;
                    }
            }
        }
        [NpcAttribute(NpcID.WinQuestBattleField)]
        public static void Win1(Client.GameClient client, ServerSockets.Packet stream, byte Option, string Input, uint id)
        {
            Dialog WinQuestThugLife = new Dialog(client, stream);
            switch (Option)
            {
                case 0:
                    {
                        WinQuestThugLife.AddText("Hey there " + client.Player.Name + " Would you like to claim your Prize?.");
                        WinQuestThugLife.AddOption("Yes Please", 1);
                        WinQuestThugLife.AddOption("Tc", 2);
                        WinQuestThugLife.AddOption("I don't care.", 255).AddAvatar(80).FinalizeDialog();

                        break;
                    }
                case 1:
                    {
                        DateTime Now64 = DateTime.Now;
                        int alive = 0;
                        foreach (Client.GameClient Entitys in Pool.GamePoll.Values)
                            if (Entitys.Player.Map == 1486 && Entitys.Player.Alive && client.Player.HitPoints >= 1)
                                alive++;
                        if (Now64.Minute >= 10 && Now64.Minute <= 59)
                        {
