                            data.AddText("Please make 1 more space in you inventory.")
                   .AddOption("Let me check.", 255).AddAvatar(67)
            .FinalizeDialog();
                            break;
                        }
                        if (client.Player.QuestGUI.FinishQuest(ActiveQuest.MissionId))
                        {
                            client.Inventory.Add(stream, 3200344);
