                              .AddOption("I~haven`t~decided,~yet!", 255)
                       .FinalizeDialog();

                            }
                            else
                                goto case 3;
                        }
                        else
                        {
                            data.AddText("It seems you don`t have enough CPs to refresh the level of reward. Please make sure you bring enough money, next time.")
                             .AddOption("Alright.", 255)
                      .FinalizeDialog();
                        }
                        break;
                    }
                case 3:
                    {
                        if (client.Player.ConquerPoints >= 20)
                        {
                            if (client.InTrade) return;
                            client.Player.ConquerPoints -= 20;
                            Game.MsgTournaments.MsgSchedules.TowerOfMystery.GenerateReward(client);
                            goto case 1;

                        }
                        else
                        {
                            data.AddText("It seems you don`t have enough CPs to refresh the level of reward. Please make sure you bring enough money, next time.")
                             .AddOption("Alright.", 255)
                      .FinalizeDialog();
                        }
                        break;
                    }

            }
        }
        [NpcAttribute(NpcID.EighthNoteFlora)]
        public static void EighthNoteFlora(Client.GameClient client, ServerSockets.Packet stream, byte Option, string Input, uint id)
        {
            Dialog data = new Dialog(client, stream);
            switch (Option)
            {
                case 0:
                    {
                        if(client.Inventory.Contain(729265, 1) && client.Inventory.Contain(729266, 1) && client.Inventory.Contain(729267, 1)
                            && client.Inventory.Contain(729268, 1) && client.Inventory.Contain(729269, 1) && client.Inventory.Contain(729270, 1)
                            && client.Inventory.Contain(729271, 1) && DailyQuests.EighthNote.HasGift(client.AccountName(client.Player.Name), "1"))
                        {
                            data.AddText("Welcome Back Hero I see that you discovered the “Eighth Note”, congratulations it's time to be rewarded.")
                           .AddOption("Claim My Reword", 2)
                           .AddOption("I'm Not Sure yet.", 255)
                           .AddAvatar(55)
                           .FinalizeDialog();
                        }
                        else if (DailyQuests.EighthNote.HasGift(client.AccountName(client.Player.Name), "0"))
                        {
                            data.AddText("You Have given your reward already what else do you want?!!")
                           .AddOption("My Bad", 255)
                           .AddAvatar(55)
                           .FinalizeDialog();
                        }
                        //else if(!client.Inventory.Contain(729265, 1))
                        //{
                        //   data.AddText("I think you need some help with you frist note i will give you a small hint : in the market if the main town you will find the old beast talk to him and he will tell you what he knows.")
                        //  .AddOption("Open the gate to him", 3)
                        //  .AddOption("Thanks", 255)
                        //  .AddAvatar(55)
                        //  .FinalizeDialog();
                        //}
                        //else if (!client.Inventory.Contain(729266, 1))
                        //{

                        //}
                        //else if (!client.Inventory.Contain(729267, 1))
                        //{

                        //}
                        //else if (!client.Inventory.Contain(729268, 1))
                        //{

                        //}
                        //else if (!client.Inventory.Contain(729269, 1))
                        //{

                        //}
                        //else if (!client.Inventory.Contain(729270, 1))
                        //{

                        //}
                        //else if (!client.Inventory.Contain(729270, 1))
                        //{

                        //}

                        else
                        {
                            data.AddText("Hello Dear " + client.Player.Name + ", Maestro Lyra, once a renowned composer, spends his days wandering the streets of the city, humming melodies only he can hear. He claims to have discovered the “Eighth Note,” a mysterious sound that transcends the seven basic notes.");
                            data.AddText("According to Lyra, this elusive note holds the power to unlock ancient harmonies that can manipulate time and space itself.");
                            data.AddText("He speaks of an old legend passed down by musicians of old: when the right sequence of sharps and flats aligns with the seven notes, the hidden note will reveal itself. Many dismiss him as a madman, but adventurers seeking hidden power listen closely to his tales, hoping to uncover the truth behind the forgotten music.");
                            data.AddText("Would you like to accompany me on my journey?")
                           .AddOption("Let's go", 1)
                           .AddOption("Well, I think about this", 255)
                           .AddAvatar(55)
                           .FinalizeDialog();
                        }
                        break;
                    }
                case 1:
                    {
                        if (DailyQuests.EighthNote.OldHero(client.AccountName(client.Player.Name)))
                        {
                            client.Teleport(83, 75, 1044);
                        }
                        else
                        {
                            new DBFunctionality.MySqlCommand(DBFunctionality.MySqlCommandType.INSERT).Insert("dailyquest").Insert("UID", client.Player.UID).Insert("Username", client.AccountName(client.Player.Name)).Insert("EighthNote", "1").Execute();
                            client.Teleport(83, 75, 1044);
                        }
                        break;
                    }
                case 2:
                    {
                        if(client.Inventory.HaveSpace(6))
                        {
                            uint[] FullNote = { 729265, 729266, 729267, 729268, 729269, 729270, 729271 };
                            foreach(uint item in FullNote)
                            {
                                client.Inventory.Remove(item, 1, stream);
                            }
                            new DBFunctionality.MySqlCommand(DBFunctionality.MySqlCommandType.UPDATE).Update("dailyquest").Set("EighthNote", "0").Where("Username", client.AccountName(client.Player.Name)).And("UID",client.Player.UID).Execute();
                            foreach (uint item in DailyQuests.EighthNote.QusetReward)
                            {
                                client.Inventory.Add(stream, item);
                            }
                            client.SendSysMesage("Congratulation, you have rewarded with " + DailyQuests.EighthNote.ConquerPoints.ToString() +" Cps, "+ DailyQuests.EighthNote.OnlineMinutes.ToString() +" Money and Another items ", MsgMessage.ChatMode.SystemWhisper);
                            client.Player.ConquerPoints += Convert.ToInt32(DailyQuests.EighthNote.ConquerPoints);
                            client.Player.Money += DailyQuests.EighthNote.Money;
                            client.Player.OnlineMinutes += DailyQuests.EighthNote.OnlineMinutes;
                        }
                        else
                        {
                            client.CreateBoxDialog("You need at least 5 Spaces In your Inventory.");
                        }
                        break;
                    }

            }
        }
