        [NpcAttribute(NpcID.GarmentPacket)]
        public static void GarmentPacket(Client.GameClient client, ServerSockets.Packet stream, byte Option, string Input, uint id)
        {

            Dialog data = new Dialog(client, stream);
            switch (Option)
            {
                case 0:
                    {
                        if (!client.Inventory.HaveSpace(1))
                        {
                            data.AddText("Please make 1 more space in your inventory.")
                      .AddOption("Let me check.", 255).AddAvatar(7)
                      .FinalizeDialog();
                            break;
                        }
                        data.AddText("Select the Garment you need.");
                        byte page = (byte)(Option + 1);
                        int tocount = (int)Math.Min(Database.CoatStorage.GarmentsBig.Count, (page * 10));
                        for (int x = page - 1; x < tocount; x++)
                        {
                            var garment = Database.CoatStorage.GarmentsBig[x];
                            Database.ItemType.DBItem DBInfo;
                            if (Database.ItemType.Garments.TryGetValue(garment.ID, out DBInfo))
                            {
                                data.AddOption("" + DBInfo.Name + "(" + garment.Stars + "Stars)", (byte)(100 + x));
                            }

                        }
                        data.AddOption("Next Page", page)
                    .AddAvatar(7)
                    .FinalizeDialog();
                        break;
                    }
                default:
                    {
                        if (Option < 100)
                        {
                            data.AddText("Select the Garment you need.");
                            byte page = (byte)(Option + 1);
                            int tocount = (int)Math.Min(Database.CoatStorage.GarmentsBig.Count, (page * 10));
                            for (int x = (page - 1) * 10; x < tocount; x++)
                            {
                                var garment = Database.CoatStorage.GarmentsBig[x];
                                Database.ItemType.DBItem DBInfo;
                                if (Database.ItemType.Garments.TryGetValue(garment.ID, out DBInfo))
                                {
                                    data.AddOption("" + DBInfo.Name + "(" + garment.Stars + "Stars)", (byte)(100 + x));
                                }

                            }
                            if (tocount % 10 == 0)
                                data.AddOption("Next Page", page);
                            data.AddAvatar(7)
                            .FinalizeDialog();
                        }
                        else //get garment.
                        {
                            client.Player.BuyItemS = Database.CoatStorage.GarmentsBig[Option - 100].ID;
                            Database.ItemType.DBItem DBInfo;
                            if (Database.ItemType.Garments.TryGetValue(client.Player.BuyItemS, out DBInfo))
                            {
                                data.AddText("Are you sure you wanna buy this garment (" + DBInfo.Name + ")?!")
                          .AddOption("Sure.", 250)
                          .AddOption("Show me the garment.", 251)
                          .AddOption("Let me check.", 255).AddAvatar(7)
                          .FinalizeDialog();
                            }
                        }

                        break;
                    }
                case 250:
                    {
                        if (!client.Inventory.HaveSpace(1))
                        {
                            data.AddText("Please make 1 more space in your inventory.")
                      .AddOption("Let me check.", 255).AddAvatar(7)
                      .FinalizeDialog();
                            break;
                        }
                        if (client.Player.BuyItemS != 0 && client.Player.ContainRechargeType(Role.Player.RechargeType.OneGarment) == false)
                        {
                            client.Player.AddRechargeFlag(Role.Player.RechargeType.OneGarment);

                            client.Inventory.Add(stream, client.Player.BuyItemS);
                            Database.ItemType.DBItem DBInfo;
                            if (Database.ItemType.Garments.TryGetValue(client.Player.BuyItemS, out DBInfo))
                                client.CreateBoxDialog("You received 1 " + DBInfo.Name + "");
                            client.Player.BuyItemS = 0;

                        }
                        break;
                    }
                case 251:
                    {

                        Database.ItemType.DBItem DBInfo;
                        if (Database.ItemType.Garments.TryGetValue(client.Player.BuyItemS, out DBInfo))
                        {
                            new MsgGameItem().FakeChatItem(client.Player.BuyItemS, DBInfo.Durability).Send(client, stream);

                            data.AddText("Are you sure you wanna buy this garment (" + DBInfo.Name + ")?!")
                                .AddOption("Sure.", 250)
                                .AddOption("Show me the garment.", 251)
                                .AddOption("Let me check.", 255).AddAvatar(7)
                                .FinalizeDialog();
                        }
                        break;
                    }
            }
        }
        public static void KingDoomCrystals(Client.GameClient client, ServerSockets.Packet stream, byte Option, string Input, uint id)
        {
            //To claim a bounty, you should kill 50 enemies in the Realm.
            Dialog data = new Dialog(client, stream);
            var ActiveQuest = Database.QuestInfo.GetFinishQuest((uint)NpcID.Crystal, client.Player.Class, 35028);

            switch (Option)
            {
                case 0:
                    {

                        if (client.Player.QuestGUI.CheckQuest(ActiveQuest.MissionId, MsgQuestList.QuestListItem.QuestStatus.Accepted) == false)
                        {
                            client.SendSysMesage("You`ve already claimed a bounty today. No more to claim.", MsgMessage.ChatMode.System);
                            break;
                        }
                        if (client.Player.QuestGUI.CheckQuest(ActiveQuest.MissionId, MsgQuestList.QuestListItem.QuestStatus.Finished) == false)
                        {
                            if (!client.Inventory.HaveSpace(1))
                            {
                                data.AddText("Please make 1 more space in your inventory.")
                          .AddOption("Let me check.", 255)
                          .FinalizeDialog();
                                break;
                            }
                            if (client.Player.QuestGUI.CheckKingDomQuest(ActiveQuest.MissionId, 50))
                            {
                                client.Player.QuestGUI.FinishQuest(ActiveQuest.MissionId);
                                client.CreateBoxDialog("You`ve restored peace to the Realm by killing to enemy soldiers, and received a Realm Crystal Fragment.");

                            }
                            else
                                client.CreateBoxDialog("To claim a bounty, you should kill 50 enemies in the Realm.");
                        }
                        else
                            client.CreateBoxDialog("To claim a bounty, you should kill 50 enemies in the Realm.");

                        break;
                    }
            }

        }
        [NpcAttribute(NpcID.GuildOfficer)]
        public static void GuildOfficer(Client.GameClient client, ServerSockets.Packet stream, byte Option, string Input, uint id)
        {
            Dialog data = new Dialog(client, stream);
            switch (Option)
            {
                case 0:
                    {
                        if (MsgTournaments.MsgSchedules.NEWGUILDWAR.Proces == MsgTournaments.ProcesType.Dead)
                        {
                            data.AddText("There~is~" + NewSystem.PrizeAllTops.GuildWar.ToString() + "~CPs~income~every~week.~Guild~leader~can~claim~it~from~Monday~to~Thursday.~First~come,~First~served.")
                                .AddOption("I~would~like~to~claim~it", 1)
                           .AddOption("#Thanks .", 255).AddAvatar(110).FinalizeDialog();
                        }
                        else
                        {
                            data.AddText("Guild war is being held now. Afterwards the leader of winning guild can gain the tax income,")
                                .AddText("which can be claimed from Monday to Thursday next week.")
                            .AddOption("Ok,~I~see.", 255).AddAvatar(110).FinalizeDialog();
                        }


                        break;
                    }
                case 1:
                    {
                        if (client.Player.GuildID == MsgTournaments.MsgSchedules.NEWGUILDWAR.Winner.GuildID && client.Player.MyGuild != null && MsgTournaments.MsgSchedules.NEWGUILDWAR.Proces == MsgTournaments.ProcesType.Dead)
                        {

                            if (client.Player.GuildRank == Role.Flags.GuildMemberRank.GuildLeader && MsgTournaments.MsgSchedules.NEWGUILDWAR.Winner.LeaderReward > 0
                                 && !MsgTournaments.MsgSchedules.NEWGUILDWAR.RewardLeader.Contains(client.Player.UID))
                            {
                                //if (NPC.GuildWarPrize.HasGift(client.Player.UID.ToString(),"0"))
                                //{

                                //}
                                if (!client.Inventory.HaveSpace(3))
                                {
                                    data.AddText("Please make 3 more spaces in your inventory.").AddOption("let me check.", 255).AddAvatar(110).FinalizeDialog();
                                    break;
                                }

                                client.Player.AddSpecialTitle(MsgTitleStorage.TitleType.Conqueror, stream);
                                client.SendSysMesage("You received a title 'Conqueror'. Check your WardRobe.");

                                MsgTournaments.MsgSchedules.NEWGUILDWAR.RewardLeader.Add(client.Player.UID);

                                MsgTournaments.MsgSchedules.NEWGUILDWAR.Winner.LeaderReward = 0;
                                client.Player.ConquerPoints += (int)NewSystem.PrizeAllTops.GuildWar;
                                client.Player.Money += NewSystem.PrizeAllTops.GuildWarMoney;
                                client.Inventory.Add(stream, 723467, 1); //goldprize reword

                                client.Player.AddFlag(MsgServer.MsgUpdate.Flags.TopGuildLeader, Role.StatusFlagsBigVector32.PermanentFlag, false);
                                client.Player.SendString(stream, MsgStringPacket.StringID.Effect, id, true, "firemagic");
                                Server.SendGlobalPacket(new MsgServer.MsgMessage("" + client.Player.Name + " , GuildLeader from " + client.Player.MyGuild.GuildName + " was rewarded with " + NewSystem.PrizeAllTops.GuildWar.ToString() + " ConquerPoints and 1 LordToken for the domination the NEWGUILDWAR.", MsgServer.MsgMessage.MsgColor.red, MsgServer.MsgMessage.ChatMode.TopLeft).GetArray(stream));
                            }
                            else if (client.Player.GuildRank == Role.Flags.GuildMemberRank.DeputyLeader && MsgTournaments.MsgSchedules.NEWGUILDWAR.Winner.DeputiLeaderReward > 0
                                && !MsgTournaments.MsgSchedules.NEWGUILDWAR.RewardDeputiLeader.Contains(client.Player.UID))
                            {
                                if (!client.Inventory.HaveSpace(4))
                                {
                                    data.AddText("Please make 4 more spaces in your inventory.")
                                   .AddOption("Let me check.", 255).AddAvatar(110).FinalizeDialog();
                                    break;
                                }
                                client.Inventory.Add(stream, Database.ItemType.PowerExpBall, 4);

                                MsgTournaments.MsgSchedules.NEWGUILDWAR.Winner.DeputiLeaderReward -= 1;
                                MsgTournaments.MsgSchedules.NEWGUILDWAR.RewardDeputiLeader.Add(client.Player.UID);
                                client.Player.AddFlag(MsgServer.MsgUpdate.Flags.TopDeputyLeader, Role.StatusFlagsBigVector32.PermanentFlag, false);
                                client.Player.SendString(stream, MsgStringPacket.StringID.Effect, id, true, "firemagic");
                            }
                            else
                            {
                                data.AddText("Just the GuildLeader or DeputiLeader can claim the reward!")
                        .AddOption("Ok~thank~you.", 255).AddAvatar(110).FinalizeDialog();
                            }
                        }
                        else
                        {
                            data.AddText("Your~guild~has~not~dominated~guild~area.~Guild~war~will~be~held~on~every~Saturday,~lasting~2~days.")
                        .AddOption("Ok~thank~you.", 255).AddAvatar(110).FinalizeDialog();
                        }


                        break;
                    }
            }
        }
