        [NpcAttribute(NpcID.PokerMillionaireLee)]
        public static void PokerMillionaireLee(Client.GameClient client, ServerSockets.Packet stream, byte Option, string Input, uint id)
        {
            Dialog data = new Dialog(client, stream);
            switch (Option)
            {
                case 0:
                    {
                        data.AddText("Good day! It seems you`ve earned a lot here. However, carrying too much          Silver may bring you into trouble. If you also have that concem, I can help you pack Silver into bags.");
                        data.AddOption("Pack~my~Silver.", 1)
                            .AddOption("I`ll find you if I need.", 255)
                           .AddAvatar(7).FinalizeDialog();

                        break;
                    }




                case 1:
                    {

                        data.AddText("Good choice! You can just pay 100,000 Silver to pack 50,000.000 Silver into a Medium Silver Bag or pack 100,000,000 Silver into a Big Silver Bag.");
                        // .AddText("~100,000,000,000 Silver into a Big Silver Bag.");
                        data.AddOption("Pack 50,000,000 Silver.", 4)//3
                            .AddOption("Pack 100,000,000 Silver.", 2)//1
                           .AddAvatar(7).FinalizeDialog();
                        break;
                    }
                case 2:
                    {
                        data.AddText("Are you sure you want to pay 100,000 Silver to pack 100,000,000 Silver into a Big Silver Bag?");
                        data.AddOption("Yes.", 5)
                            .AddOption("No.", 255)
                           .AddAvatar(7).FinalizeDialog();

                        break;
                    }
                case 3:
                    {
                        if (client.PokerPlayer != null)
                            return;
                        if (!client.Player.IsCheckedPass)
                            return;
                        if (client.Inventory.HaveSpace(1) == false)
                        {
                            data.AddText("Please make 1 more space in your inventory.");
                            data.AddOption("Let me check.", 255)
                               .AddAvatar(7).FinalizeDialog();
                            break;
                        }
                        if (client.Player.Money >= 50100000)
                        {
                            client.Player.Money -= 50100000;
                            client.Player.SendUpdate(stream, client.Player.Money, MsgUpdate.DataType.Money);
                            client.Inventory.Add(stream, 3005836);
                            String folderN = DateTime.Now.Year + "-" + DateTime.Now.Month,
            Path = "Cache\\Logs\\Poker\\PackMoney[100]\\",
            NewPath = System.IO.Path.Combine(Path, folderN);
                            if (!File.Exists(NewPath + folderN))
                            {
                                System.IO.Directory.CreateDirectory(System.IO.Path.Combine(Path, folderN));
                            }
                            if (!File.Exists(NewPath + "\\" + DateTime.Now.Day + ".txt"))
                            {
                                using (System.IO.FileStream fs = System.IO.File.Create(NewPath + "\\" + DateTime.Now.Day + ".txt"))
                                {
                                    fs.Close();
                                }
                            }
                            using (System.IO.StreamWriter file = new System.IO.StreamWriter(NewPath + "\\" + DateTime.Now.Day + ".txt", true))
                            {
                                file.WriteLine("UserName[Acc] |" + client.Player.Name + "| UIDAccount |" + client.Player.UID + " | IPAccount | " + client.Socket.RemoteIp + " | MacID |" + client.MacAddress + "|  PasswordAccount  [" + client.Player.IsCheckedPass + "] [The Clock] " + DateTime.Now.Hour + ":" + DateTime.Now.Minute + ":" + DateTime.Now.Second);
                                file.Close();
                            }
                        }
                        else
                        {
                            data.AddText("Sorry, you don`t have 50,100,000 Silver in total.");
                            data.AddOption("My~bad.", 255)
                               .AddAvatar(7).FinalizeDialog();
                        }
                        break;
                    }
                case 4:
                    {
                        data.AddText("Are you sure you want to pay 100,000 Silver to pack 50,000,000 Silver into a Medium Silver Bag?");
                        data.AddOption("Yes.", 3)
                            .AddOption("No.", 255)
                           .AddAvatar(7).FinalizeDialog();

                        break;
                    }
                case 5:
                    {
                        if (client.PokerPlayer != null)
                            return;
                        if (!client.Player.IsCheckedPass)
                            return;
                        if (client.Inventory.HaveSpace(1) == false)
                        {
                            data.AddText("Please make 1 more space in your inventory.");
                            data.AddOption("Let me check.", 255)
                               .AddAvatar(7).FinalizeDialog();
                            break;
                        }
                        if (client.Player.Money >= 100100000)
                        {
                            client.Player.Money -= 100100000;
                            client.Player.SendUpdate(stream, client.Player.Money, MsgUpdate.DataType.Money);
                            client.Inventory.Add(stream, 3005837);
                            String folderN = DateTime.Now.Year + "-" + DateTime.Now.Month,
           Path = "Cache\\Logs\\Poker\\PackMoney[500]\\",
           NewPath = System.IO.Path.Combine(Path, folderN);
                            if (!File.Exists(NewPath + folderN))
                            {
                                System.IO.Directory.CreateDirectory(System.IO.Path.Combine(Path, folderN));
                            }
                            if (!File.Exists(NewPath + "\\" + DateTime.Now.Day + ".txt"))
                            {
                                using (System.IO.FileStream fs = System.IO.File.Create(NewPath + "\\" + DateTime.Now.Day + ".txt"))
                                {
                                    fs.Close();
                                }
                            }
                            using (System.IO.StreamWriter file = new System.IO.StreamWriter(NewPath + "\\" + DateTime.Now.Day + ".txt", true))
                            {
                                file.WriteLine("UserName[Acc] |" + client.Player.Name + "| UIDAccount |" + client.Player.UID + " | IPAccount | " + client.Socket.RemoteIp + " | MacID |" + client.MacAddress + "|  PasswordAccount  [" + client.Player.IsCheckedPass + "] [The Clock] " + DateTime.Now.Hour + ":" + DateTime.Now.Minute + ":" + DateTime.Now.Second);
                                file.Close();
                            }
                        }
                        else
                        {
                            data.AddText("Sorry, you don`t have 100,100,000 Silver in total.");
                            data.AddOption("My~bad.", 255)
