        public static uint DailiHeavenCpsCost(uint Stage)
        {
            if (Stage == 1)
                return 5;
            if (Stage == 2)
                return 20;
            if (Stage == 3)
                return 35;
            if (Stage == 4)
                return 100;
            return 0;
