                        {
                            data.AddText("Have you met my father on the Wind Plain (442,431)? I`m sure he`ll")
                                   .AddText("~bring back lots of beautiful feathers.");
                            data.AddOption("Yeah.", 255).AddAvatar(68).FinalizeDialog();
                        }

                        break;
                    }
