                                data.AddText("Please make 1 more space in your inventory")
                                                         .AddOption("Let me check.", 255).AddAvatar(7)
                                                        .FinalizeDialog();
                            }
                        }
                        else
                        {
                            data.AddText("Sorry,~you~do~not~have~the~required~virtue~points.")
                            .AddOption("I~see.", 255)
                            .AddAvatar(7).FinalizeDialog();
                        }

                        break;
                    }

            }
