        [NpcAttribute(NpcID.PointsMonsters)]
        public static void PointsMonsters(Client.GameClient client, ServerSockets.Packet stream, byte Option, string Input, uint id)
        {
            Dialog dialog = new Dialog(client, stream);
            switch (Option)
            {
                case 0:
                    {
                        dialog.Text("Hello there, i can exchange PointsMonsters for cool things.\n");
                        dialog.Option("Check My Points.", 1);
                        dialog.Option("exchange 1000 Points to cps[100 k].", 2);
                        dialog.Option("exchange 100 k Points to Anima [P14].", 3);
                        dialog.Option("exchange 100 K Points to cps[10 m].", 4);
                        dialog.Option("I~see.", 255).FinalizeDialog();
                        break;
                    }
                case 1:
                    {
                        dialog.Text("You Current PointsMonsters: " + client.Player.PointsMonsters + " !.");
                        dialog.Option("I~see.", 255).FinalizeDialog();
                        break;
                    }
                case 2:
                    {
                        if (client.Player.PointsMonsters >= 1000)
                        {
                            client.Player.ConquerPoints += 100000;
                            client.Player.PointsMonsters -= 1000;
                        }
                        else
                            client.Player.MessageBox("sorry you dont have 1000 points", null, null);
                        break;
                    }
                case 3:
                    {
                        if (client.Player.PointsMonsters >= 100000)
                        {
                            client.Inventory.Add(stream, 4200014, 1, 0, 0, 0, Role.Flags.Gem.NoSocket, Role.Flags.Gem.NoSocket, false);
                            client.Player.PointsMonsters -= 100000;
                        }
                        else
                            client.Player.MessageBox("sorry you dont have 100 k points", null, null);
                        break;
                    }
                case 4:
                    {
                        if (client.Player.PointsMonsters >= 100000)
                        {
                            client.Player.ConquerPoints += 10000000;
                            client.Player.PointsMonsters -= 100000;
                        }
                        else
                            client.Player.MessageBox("sorry you dont have 100 k points", null, null);
                        break;
                    }
            }
        }
