        [NpcAttribute(NpcID.SillerVip)]
        public static void SillerVip(Client.GameClient client, ServerSockets.Packet stream, byte Option, string Input, uint id)
        {
            Dialog dialog = new Dialog(client, stream);
            switch (Option)
            {
                case 0:
                    {
                        dialog.Text("Hello there, i can exchange CPS for Vip.\n");
                        dialog.Text("Wanna proceed? Here are my options.\n");
                        dialog.Text("You current CPS: " + client.Player.ConquerPoints + ".\n");
                        dialog.Option("12-hour VIP 4[2,500,000].", 1);
                        dialog.Option("24-hour VIP 4[5,000,000].", 2);
                        dialog.Option("12-hour VIP 5[7,500,000].", 3);
                        dialog.Option("24-hour VIP 5[10,000,000].", 4);
                        // dialog.Option("12-hour VIP 6[100,000].", 5);
                        //  dialog.Option("24-hour VIP 6[200,000].", 6);
                        dialog.Option("I~see.", 255).FinalizeDialog();
                        break;
                    }
                case 1:
                    {
                        if (client.Player.ConquerPoints >= 2500000)
                        {
                            if (client.Player.VipLevel == 0)
                            {
                                client.Player.ConquerPoints -= 2500000;
                                client.Player.ExpireVip = DateTime.Now.AddHours(12);

                                client.Player.VipLevel = 4;
                                client.Player.SendUpdate(stream, client.Player.VipLevel, MsgUpdate.DataType.VIPLevel);

                                client.Player.UpdateVip(stream);
                                client.SendSysMesage("You have 12 hour(s) of VIP service remaining.", MsgMessage.ChatMode.System, MsgMessage.MsgColor.red);
                                dialog.Text("Congratulations! You've got 12-hour VIP 4 Service!");

                                dialog.Option("Thanks.", 255).FinalizeDialog();
                            }
                            else
                            {
                                dialog.Text("Hey hey! you already have VIP " + client.Player.VipLevel + "!");

                                dialog.Option("I~see.", 255).FinalizeDialog();
                            }
                        }
                        else
                        {
                            dialog.Text("Hey hey! you don't have the required amount of CPS!");

                            dialog.Option("I~see.", 255).FinalizeDialog();
                        }
                        break;
                    }
                case 2:
                    {
                        if (client.Player.ConquerPoints >= 5000000)
                        {
                            if (client.Player.VipLevel == 0)
                            {
                                client.Player.ConquerPoints -= 5000000;
                                client.Player.ExpireVip = DateTime.Now.AddHours(24);

