                                {
                                    data.AddOption("Run it 5 times more.", 3)
                                   .AddOption("I see.", 255).FinalizeDialog();
                                }
                            }
                            else
                            {
                                data.AddText("Please come back when you will have 5 TreasureLeaf in your inventory.")
