                            {
                                data.AddText("Sorry, you are not in top 8 in Skill Pk Tournament or you claimed the reward.")
                        .AddOption("Okay.", 255).AddAvatar(154).FinalizeDialog();
                            }
                        }
                        else
                        {
                            data.AddText("Please make one space in your bag.")
                          .AddOption("Okay.", 255).AddAvatar(154).FinalizeDialog();
                        }

                        break;
                    }

            }
        }
