        [NpcAttribute(NpcID.LeftGate)]
        public static void LeftGate(Client.GameClient client, ServerSockets.Packet stream, byte Option, string Input, uint id)
        {
            if (MsgSchedules.NEWGUILDWAR.Winner.GuildID != client.Player.GuildID)
                return;
            Dialog obj = new Dialog(client, stream);
            switch (Option)
            {

                case 0:
                    {
                        if (MsgSchedules.NEWGUILDWAR.LeftGateDemolition)
                        {
                            if ((client.Player.GuildRank == Role.Flags.GuildMemberRank.DeputyLeader || client.Player.GuildRank == Role.Flags.GuildMemberRank.GuildLeader) && MsgSchedules.NEWGUILDWAR.Winner.GuildID == client.Player.GuildID)
                            {
                                obj.AddText("Would~you~like~to~repair~the~damaged~gate");
                                obj.AddOption("Repair~now.", 3);
                                obj.AddOption("No", 255);
                                obj.AddAvatar(110);
                                obj.FinalizeDialog();
                                break;
                            }
                        }
                        if (MsgSchedules.NEWGUILDWAR.LeftGateOpen)
                        {
                            if ((client.Player.GuildRank == Role.Flags.GuildMemberRank.DeputyLeader || client.Player.GuildRank == Role.Flags.GuildMemberRank.GuildLeader) && MsgSchedules.NEWGUILDWAR.Winner.GuildID == client.Player.GuildID)
                            {
                                obj.AddText("Would~you~like~to~close~the~gate？");
                                obj.AddOption("Yes", 2);
                                obj.AddOption("No", 255);
                                obj.AddAvatar(110);
                                obj.FinalizeDialog();
                            }
                            break;
                        }
                        obj.AddText("Would~you~like~to~enter~the~Guild~House");
                        obj.AddOption("yes", 1);
                        obj.AddOption("Open~the~gate", 2);
                        obj.AddOption("Just~passing~by", 255);
                        obj.AddAvatar(110);
                        obj.FinalizeDialog();
                        break;
                    }
                case 1:
                    {
                        if (client.Player.GuildID == MsgSchedules.NEWGUILDWAR.Winner.GuildID)
                        {
                            client.Teleport(162, 192, 1038);
                        }
                        break;
                    }
                case 2:
                    {
                        if ((client.Player.GuildRank == Role.Flags.GuildMemberRank.DeputyLeader || client.Player.GuildRank == Role.Flags.GuildMemberRank.GuildLeader) && MsgSchedules.NEWGUILDWAR.Winner.GuildID == client.Player.GuildID)
                        {
                            Guild GETWinner;
                            if (Guild.GuildPoll.TryGetValue(MsgSchedules.NEWGUILDWAR.Winner.GuildID, out GETWinner))
                            {
                                foreach (var c_guild in GETWinner.Constructs.Values)
                                {
                                    if (c_guild.ID == 1)
                                    {
                                        if (MsgSchedules.NEWGUILDWAR.LeftGateOpen)
                                        {
                                            MsgSchedules.NEWGUILDWAR.NPC_INFO[MsgGuildWar.NPCID.LeftGate].Npc.Mesh = (SobNpc.StaticMesh)MsgSchedules.NEWGUILDWAR.GateClose(c_guild.Level, false);
                                        }
                                        else if (!MsgSchedules.NEWGUILDWAR.LeftGateDemolition)
                                        {
                                            MsgSchedules.NEWGUILDWAR.NPC_INFO[MsgGuildWar.NPCID.LeftGate].Npc.Mesh = (SobNpc.StaticMesh)MsgSchedules.NEWGUILDWAR.GateOpen(c_guild.Level, false);
                                        }
                                    }
                                }
                                MsgSchedules.NEWGUILDWAR.NPC_INFO[MsgGuildWar.NPCID.LeftGate].Npc.SendView(MsgSchedules.NEWGUILDWAR.NPC_INFO[MsgGuildWar.NPCID.LeftGate].Npc.GetArray(stream, false), MsgSchedules.NEWGUILDWAR.Map);
                            }
                        }
                        break;
                    }
                case 3:
                    {
                        if (MsgSchedules.NEWGUILDWAR.LeftGateDemolition)
                        {
                            if ((client.Player.GuildRank == Flags.GuildMemberRank.DeputyLeader || client.Player.GuildRank == Flags.GuildMemberRank.GuildLeader) && MsgSchedules.NEWGUILDWAR.Winner.GuildID == client.Player.GuildID)
                            {
                                Guild GetWinner;
                                if (Guild.GuildPoll.TryGetValue(MsgSchedules.NEWGUILDWAR.Winner.GuildID, out GetWinner))
                                {
                                    if (GetWinner.Info.SilverFund >= 300000)
                                    {
                                        GetWinner.Info.SilverFund -= 300000;
                                        MsgSchedules.NEWGUILDWAR.NPC_INFO[MsgGuildWar.NPCID.LeftGate].Npc.Mesh = (SobNpc.StaticMesh)MsgGuildWar.StaticMesh.LeftGate;
                                        MsgSchedules.NEWGUILDWAR.NPC_INFO[MsgGuildWar.NPCID.LeftGate].Npc.MaxHitPoints = 10000000;
                                        foreach (var c_guild in GetWinner.Constructs.Values)
                                        {
                                            if (c_guild.ID == 1)
                                            {
                                                MsgSchedules.NEWGUILDWAR.NPC_INFO[MsgGuildWar.NPCID.LeftGate].Npc.MaxHitPoints = (int)c_guild.Data.Data;
                                                MsgSchedules.NEWGUILDWAR.NPC_INFO[MsgGuildWar.NPCID.LeftGate].Npc.GuildID = MsgSchedules.NEWGUILDWAR.Winner.GuildID;
                                                MsgSchedules.NEWGUILDWAR.NPC_INFO[MsgGuildWar.NPCID.LeftGate].Npc.Mesh = (SobNpc.StaticMesh)MsgSchedules.NEWGUILDWAR.GateClose(c_guild.Level, false);
                                            }
                                        }

                                        MsgSchedules.NEWGUILDWAR.NPC_INFO[MsgGuildWar.NPCID.LeftGate].Npc.HitPoints = MsgSchedules.NEWGUILDWAR.NPC_INFO[MsgGuildWar.NPCID.LeftGate].Npc.MaxHitPoints;
                                        MsgSchedules.NEWGUILDWAR.NPC_INFO[MsgGuildWar.NPCID.LeftGate].Npc.SendView(MsgSchedules.NEWGUILDWAR.NPC_INFO[MsgGuildWar.NPCID.LeftGate].Npc.GetArray(stream, false), MsgSchedules.NEWGUILDWAR.Map);

                                    }
                                    else
                                    {
                                        client.SendSysMesage("402976_1010@@");

                                    }
                                }
                            }

                        }

                        break;
                    }
            }
        }
