                                                MsgSchedules.NEWGUILDWAR.NPC_INFO[MsgGuildWar.NPCID.RightGate].Npc.Mesh = (SobNpc.StaticMesh)MsgSchedules.NEWGUILDWAR.GateClose(c_guild.Level, true);
                                            }
                                        }

                                        MsgSchedules.NEWGUILDWAR.NPC_INFO[MsgGuildWar.NPCID.RightGate].Npc.HitPoints = MsgSchedules.NEWGUILDWAR.NPC_INFO[MsgGuildWar.NPCID.RightGate].Npc.MaxHitPoints;
                                        MsgSchedules.NEWGUILDWAR.NPC_INFO[MsgGuildWar.NPCID.RightGate].Npc.SendView(MsgSchedules.NEWGUILDWAR.NPC_INFO[MsgGuildWar.NPCID.RightGate].Npc.GetArray(stream, false), MsgSchedules.NEWGUILDWAR.Map);
                                    }
                                    else
                                    {
                                        client.SendSysMesage("402976_1010@@");
                                    }
                                }
                            }
                        }

                        break;
                    }
            }
        }

        [NpcAttribute(NpcID.SuperGuildWar_CasteleLeftGate)]
