        [NpcAttribute(NpcID.GuildConductor)]
        public static void GuildConductor(Client.GameClient client, ServerSockets.Packet stream, byte Option, string Input, uint id)
        {
            Dialog data = new Dialog(client, stream);
            switch (Option)
            {
                case 0:
                    {
                        data.AddText("What~Can~I~Do~For~You?")
                                                .AddOption("Enter~The~Guild~Area .", 1)
                                                .AddOption("#ThX .", 255)
                                                .AddAvatar(123).FinalizeDialog();

                        break;
                    }
                case 1:
                    {
                        if (Game.MsgTournaments.MsgSchedules.NEWGUILDWAR.Proces == MsgTournaments.ProcesType.Alive)
                        {
                            byte RandTele = (byte)Pool.GetRandom.Next(1, 14);
                            switch (RandTele)
                            {
                                case 1: client.Teleport(326, 374, 1038); break;
                                case 2: client.Teleport(299, 371, 1038); break;
                                case 3: client.Teleport(293, 352, 1038); break;
                                case 4: client.Teleport(262, 337, 1038); break;
                                case 5: client.Teleport(285, 324, 1038); break;
                                case 6: client.Teleport(315, 289, 1038); break;
                                case 7: client.Teleport(323, 268, 1038); break;
                                case 8: client.Teleport(351, 282, 1038); break;
                                case 9: client.Teleport(371, 305, 1038); break;
                                case 10: client.Teleport(370, 326, 1038); break;
                                case 11: client.Teleport(357, 335, 1038); break;
                                case 12: client.Teleport(333, 330, 1038); break;
                                default: client.Teleport(322, 321, 1038); break;
                            }
                        }
                        else
                        {
                            client.Teleport(349, 340, 1038);
                        }
                        if (client.Player.ContainFlag(MsgUpdate.Flags.Ride))
                            client.Player.RemoveFlag(MsgUpdate.Flags.Ride);
                        break;
                    }
            }
        }
        [NpcAttribute(NpcID.CaptureTheFlag)]
        public static void CaptureTheFlag(Client.GameClient client, ServerSockets.Packet stream, byte Option, string Input, uint id)
        {
            Dialog data = new Dialog(client, stream);
            switch (Option)
            {
                case 0:
                    {
                        data.AddText("What~Can~I~Do~For~You?")
                                                .AddOption("Claim~The~CTF~Reward .", 4)
                                                .AddOption("Sign~Up~Capture~The~Flag .", 5)
                                                .AddOption("#ThX .", 255)
                                                .AddAvatar(123).FinalizeDialog();
                        break;
                    }
                case 4:
                    {
                        if (Game.MsgTournaments.MsgSchedules.CaptureTheFlag.Proces == MsgTournaments.ProcesType.Dead)
                        {
                            if (client.Player.MyGuild != null && client.Player.MyGuild.CTF_Rank >= 1 && client.Player.MyGuild.CTF_Rank <= 4)
                            {
                                if (client.Player.MyGuildMember.CTF_Claimed == 1)
                                {
                                    data.AddText("Sorry, you already claimed the reward.")
            .AddOption("Ah~yes.", 255).AddAvatar(110).FinalizeDialog();
                                    break;
                                }
                                #region Rank 1
                                if (client.Player.MyGuild != null && client.Player.MyGuild.CTF_Rank == 1)
                                {
                                    if (client.Player.GuildRank == Role.Flags.GuildMemberRank.GuildLeader)
                                    {
                                        if (client.Player.MyGuild.ClaimCtfReward == 1)
                                        {
                                            data.AddText("Sorry, you already claimed the reward.")
                                            .AddOption("Ah~yes.", 255).AddAvatar(110).FinalizeDialog();
                                            break;
                                        }
                                        client.Player.MyGuild.ClaimCtfReward = 1;
                                        client.Player.ConquerPoints += 20000000; //20m CPs
                                        //client.Inventory.Add(stream, 730003, 1);     // Stone +3
                                        client.Player.SendUpdate(stream, client.Player.Money, MsgUpdate.DataType.ConquerPoints);
                                       // client.Player.Money += 1000000000;
                                        client.Player.SendUpdate(stream, client.Player.Money, MsgUpdate.DataType.Money);

                                        client.Player.MyGuildMember.CTF_Claimed = 1;
                                        Server.SendGlobalPacket(new MsgServer.MsgMessage("" + client.Player.Name + " , GuildLider from " + client.Player.MyGuild.GuildName + " was rewarded  20,000,000 CPs for the domination the CaptureTheFlag Rank [ 1 ] .", MsgServer.MsgMessage.MsgColor.red, MsgServer.MsgMessage.ChatMode.TopLeft).GetArray(stream));
                                    }
                                }
                                #endregion
                                #region Rank 2
                                if (client.Player.MyGuild != null && client.Player.MyGuild.CTF_Rank == 2)
                                {
                                    if (client.Player.GuildRank == Role.Flags.GuildMemberRank.GuildLeader)
                                    {
                                        if (client.Player.MyGuild.ClaimCtfReward == 1)
                                        {
                                            data.AddText("Sorry, you already claimed the reward.")
                                            .AddOption("Ah~yes.", 255).AddAvatar(110).FinalizeDialog();
                                            break;
                                        }
                                        client.Player.MyGuild.ClaimCtfReward = 1;
                                        client.Player.ConquerPoints += 10000000; // 10m CPs
                                        //client.Inventory.Add(stream, 730003, 1);    // Stone +3
                                        client.Player.SendUpdate(stream, client.Player.Money, MsgUpdate.DataType.ConquerPoints);
                                       // client.Player.Money += 700000000;
                                        client.Player.SendUpdate(stream, client.Player.Money, MsgUpdate.DataType.Money);

                                        client.Player.MyGuildMember.CTF_Claimed = 1;
                                        Server.SendGlobalPacket(new MsgServer.MsgMessage("" + client.Player.Name + " , GuildLider from " + client.Player.MyGuild.GuildName + " was rewarded 10,000,000 CPs for the domination the CaptureTheFlag Rank [ 2 ] .", MsgServer.MsgMessage.MsgColor.red, MsgServer.MsgMessage.ChatMode.TopLeft).GetArray(stream));
                                    }
                                }
                                #endregion
                                #region Rank 3
                                if (client.Player.MyGuild != null && client.Player.MyGuild.CTF_Rank == 3)
                                {
                                    if (client.Player.GuildRank == Role.Flags.GuildMemberRank.GuildLeader)
                                    {
                                        if (client.Player.MyGuild.ClaimCtfReward == 1)
                                        {
                                            data.AddText("Sorry, you already claimed the reward.")
                                            .AddOption("Ah~yes.", 255).AddAvatar(110).FinalizeDialog();
                                            break;
                                        }
                                        client.Player.MyGuild.ClaimCtfReward = 1;
                                        client.Player.ConquerPoints += 5000000; //5m CPs
                                       // client.Inventory.Add(stream, 730003, 1);   // Stone +3
                                        client.Player.SendUpdate(stream, client.Player.Money, MsgUpdate.DataType.ConquerPoints);
                                       // client.Player.Money += 500000000;
                                        client.Player.SendUpdate(stream, client.Player.Money, MsgUpdate.DataType.Money);

                                        client.Player.MyGuildMember.CTF_Claimed = 1;
                                        Server.SendGlobalPacket(new MsgServer.MsgMessage("" + client.Player.Name + " , GuildLider from " + client.Player.MyGuild.GuildName + " was rewarded 5.000,000 CPs for the domination the CaptureTheFlag Rank [ 3 ] .", MsgServer.MsgMessage.MsgColor.red, MsgServer.MsgMessage.ChatMode.TopLeft).GetArray(stream));
                                    }
                                }
                                #endregion
                               
                            }
                            else
                            {
                                data.AddText("Sorry, your guild is not top 9.")
             .AddOption("Ah~yes.", 255).AddAvatar(110).FinalizeDialog();
                            }

                        }



                        break;
                    }
                case 5:
                    {
                        if (client.Player.MyGuild == null)
                        {
                            data.AddText("Sorry you not have Guild.")
                    .AddAvatar(123).FinalizeDialog();
                            break;
                        }
                        if (!MsgTournaments.MsgSchedules.CaptureTheFlag.Join(client, stream))
                        {
                            data.AddText("The Capture The Flag will open at Every Day ,22:00-23:00.")
                     .AddAvatar(123).FinalizeDialog();
                        }

                        break;
                    }
            }
        }

