        [NpcAttribute(NpcID.BugsNpc)]
        public static void BugsNpc(Client.GameClient client, ServerSockets.Packet stream, byte Option, string Input, uint id)
        {
            Dialog data = new Dialog(client, stream);
            switch (Option)
            {
                case 0:
                    {
                        data.AddText("Welcome In Server [ " + Program.ServerConfig.ServerName + " ], you can send bug to GM.");
                        data.AddOption("Add bug", 1);
                        data.AddOption("thank~you.", 255);
                        data.AddAvatar(263).FinalizeDialog();
                        break;
                    }
                case 1:
                    {
                        data.AddText("Please input your bug.").
                            AddInput("Message: ", 2, 128).
                            AddOption("Just passing by.")
                            .FinalizeDialog();

                        break;
                    }
                case 2:
                    {
                        if (!string.IsNullOrEmpty(Input) && Input.Length > 0 && Input.Length <= 128)
                        {
                            Database.ServerDatabase.LoginQueue.Enqueue("[Bugs] Name Player " + client.Player.Name + " BUG:" + Input + "\n\n");
                            client.Player.MessageBox("Your message has been sent to GM thank you.", null, null);
                        }
                        else
                            client.Player.MessageBox("invalid Message!", null, null);

                        break;
                    }
            }
        }

