        [NpcAttribute(NpcID.DragonFurnaceForging)]
        public static void DragonFurnaceForging(Client.GameClient client, ServerSockets.Packet stream, byte Option, string Input, uint id)
        {
            Dialog dialog = new Dialog(client, stream);
            switch (Option)
            {

                case 0:
                    {
                        if (client.Player.DragonFurnaceForgeCount == 0)
                        {
                            dialog.Text("      This ancient furnace contains wonder energy to forge Anima.");
                            dialog.Text("~After you put in an Anima, you can forge it up 8 times in a row.");
                            dialog.Text("~If you changed your mind, you can stop forging and take it out at any time.\n");

                            dialog.Option("Start~forging.‚", 1);
                            dialog.Option("Tell~me~more.", 10).FinalizeDialog();
                        }
                        else
                        {
                            if (client.Player.DragonFurnaceForge == 0)
                            {
                                dialog.Text("+------------------------ Forging Failed ------------------------+\n");
                                dialog.Text("                The Anima vanished into air.\n");
                                dialog.Text("+----------------------------------------------------------------+\n");

                                dialog.Option("Put~in~another~Anima.‚", 1).FinalizeDialog();
                            }
                            else
                            {
                                dialog.Text("+----------------------------------------------------------------+\n");
                                dialog.Text("                  *" + Pool.ItemsBase[client.Player.DragonFurnaceForge].Name + "*\n");
                                dialog.Text("+----------------------------------------------------------------+\n");
                                dialog.Text("       The forging is successful, and your Anima is upgraded by " + (client.Player.DragonFurnaceForge - client.Player.DragonFurnace).ToString() + " phase(s)!\n");
                                dialog.Text("       You've forged it " + client.Player.DragonFurnaceForgeCount + "/8 time(s) this round, Continue the forging?\n");


                                dialog.Option("Continue~the~forging.‚", 3);
                                dialog.Option("Stop~forging.‚", 2).FinalizeDialog();
                            }
                        }
                        break;
                    }
                case 1:
                    {
                        if (client.Inventory.Contain(client.Player.DragonFurnace, 1))
                        {
                            client.Player.AddPick(new ServerSockets.RecycledPacket().GetStream(), "Forging...", 2);
                            client.Inventory.Remove(client.Player.DragonFurnace, 1, new ServerSockets.RecycledPacket().GetStream());
                            client.Player.DragonFurnaceForgeCount++;
                            if (Role.Core.Rate(50))
                            {
                            again:
                                var Chances = Database.SpiritTable.SpiritRates.Where(z => z.AnimaID == client.Player.DragonFurnace).ToArray();
                                Chances = Chances.Where(z => z.Type != Database.SpiritTable.Type.Failed).ToArray();
                                /*  var r = Pool.GetRandom.Next(0, Chances.Count());
                                  Chances = Chances.Where(q => q.Index == Chances.ToArray()[r].Index).ToArray();*/
                                Chances = Chances.OrderBy(q => q.NewAnimaID).ToArray();//This is new

                                if (Chances.FirstOrDefault().Type == Database.SpiritTable.Type.Awkaned/* && Role.Core.Rate(99)*/) goto again;
                                client.Player.DragonFurnaceForge = Chances.FirstOrDefault().NewAnimaID;

                                DragonFurnaceForging(client, stream, 0, "", 0);
                            }
                            else
                            {
                                client.Player.DragonFurnaceForge = 0;
                                DragonFurnaceForging(client, stream, 0, "", 0);
                            }
                        }
                        else
                        {
                            dialog.Text("    You can`t continue forging unless you have P" + client.Player.DragonFurnace % 100 + "Anima.");
                            dialog.Option("I`ll~go~collect~some.", 255).FinalizeDialog();
                        }
                        break;
                    }
                case 2:
                    {
                        if (client.Player.DragonFurnaceForge != 0)
                        {
                            client.Inventory.Add(stream, client.Player.DragonFurnaceForge);
                            client.CreateBoxDialog("You successfully taken out a " + Pool.ItemsBase[client.Player.DragonFurnaceForge].Name + " from the Dragon Furnace and returned to Twin City.");
                        }
                        client.Player.DragonFurnaceForge = 0;
                        client.Player.DragonFurnaceForgeCount = 0;
                        client.Teleport(351, 422, 1002);
                        client.Player.SendString(stream, MsgStringPacket.StringID.Effect, true, new string[] { "moveback" });
                        break;
                    }
                case 3:
                    {
                        if (client.Player.DragonFurnaceForgeCount > 0 && client.Player.DragonFurnaceForgeCount < 8)
                        {
                            client.Player.AddPick(new ServerSockets.RecycledPacket().GetStream(), "Forging...", 2);
                            client.Inventory.Remove(client.Player.DragonFurnace, 1, new ServerSockets.RecycledPacket().GetStream());
                            client.Player.DragonFurnaceForgeCount++;
                            if (Role.Core.Rate(50))
                            {
                            again:
                                var Chances = Database.SpiritTable.SpiritRates.Where(z => z.AnimaID == client.Player.DragonFurnace).ToArray();
                                Chances = Chances.Where(z => z.Type != Database.SpiritTable.Type.Failed).ToArray();
                                /*  var r = Pool.GetRandom.Next(0, Chances.Count());
                                  Chances = Chances.Where(q => q.Index == Chances.ToArray()[r].Index).ToArray();*/
                                Chances = Chances.OrderBy(q => q.NewAnimaID).ToArray();//This is new

                                if (Chances.FirstOrDefault().Type == Database.SpiritTable.Type.Awkaned/* && Role.Core.Rate(99)*/) goto again;
                                client.Player.DragonFurnaceForge = Chances.FirstOrDefault().NewAnimaID;
                                client.Player.DragonFurnaceForgeCount++;
                                DragonFurnaceForging(client, stream, 0, "", 0);
                            }
                            else
                            {
                                client.Player.DragonFurnaceForge = 0;
                                DragonFurnaceForging(client, stream, 0, "", 0);
                            }
                        }
                        else
                        {
                            dialog.Text("Sorry, you already have forged it 8 times.");

                            dialog.Option("I~see.‚", 255).FinalizeDialog();
                        }
                        break;
                    }
                case 10:
                    {
                        dialog.Text("     Every time you put an Anima into the Furnace, you have 8 chances to forge it.");
                        dialog.Text("~After each successful forging, you can choose to Continue or Stop.");

                        dialog.Option("What`s~the~forging~success~rate?", 11).FinalizeDialog();
                        break;
                    }
                case 11:
                    {
                        dialog.Text("      There is a 55% chance of successfully forging an Anima that may upgrade the Anima`s phase.");
                        dialog.Text("~If the forging fails (45% chance), you`ll lose the Anima.");

                        dialog.Option("Start~forging.‚", 0).FinalizeDialog();
                        break;
                    }
            }
        }
