        [NpcAttribute(NpcID.LuckySmeltingList)]
        public static void LuckySmeltingList(Client.GameClient client, ServerSockets.Packet stream, byte Option, string Input, uint id)
        {
            Dialog dialog = new Dialog(client, stream);
