                        dialog.Option("Recent~successful~smelting~records.", 1);
                        dialog.Option("Close.", 255).FinalizeDialog();
                        break;
                    }
                case 1:
                    {
                        var array = Pool.SmeltingSessions.Take(10).ToList();
