                        {
                            dialog.Text("          [Furnace]         [Smelting Session]\n");
                            for (int i = array.Count - 1; i >= 0; i--)
                            {
                                dialog.Text("        <tip color=" + (Pool.SmeltingSessions[i] == 0 ? "0xff4bb52d>Solar Furnace" : "0xfff05050>Lunar Furnace") + "</tip>       Session 000" + i + "\n");
