        public static void Animas(Client.GameClient client, ServerSockets.Packet stream, byte Option, string Input, uint id)
        {
            if (!client.Player.TREPIN2 && client.Player.CheckPin())
            {
                client.Player.MessageBox("Please Active Pincode", null, null, 60);
                return;
            }
            if (client.PokerPlayer != null)
            {
                client.Player.MessageBox("Sorry not open in Poker Table", null, null, 60);
                return;
            }
            if (!client.Player.IsCheckedPass)
            {
                client.Player.MessageBox("Sorry not open in Poker Table", null, null, 60);
                return;
            }
            if (client.InTrade)
            {
                client.Player.MessageBox("Sorry not open in Trade", null, null, 60);
                return;
            }
            Dialog dialog = new Dialog(client, stream);
            switch (Option)
            {

                case 0:
                    {
                        dialog.Text("Anima contains everlasting vital power that can greatly improve equipment when embedded in.");
                        dialog.Text("You may upgrade Animae with the Dragon Furnace. It`s not always successful.");
                        dialog.Text("Anima can also be exchanged for CPs. Do you want to use this Anima now?\n");

                        dialog.Option("Yes.", 1);
                        dialog.Option("Exchange~it~for~CPs.", 2);
                        dialog.Option("Get~details~on~the~official~site.", 3);
                        dialog.Option("Watch~video~introducing~Anima.", 4);
                        dialog.Option("No,~not~now.", 255);
                        dialog.Avatar(1976).FinalizeDialog();
                        break;
                    }
                case 1:
                    {
                        dialog.Text("    With everlasting vital power, this Anima can be embedded into weapon or equipment");
                        dialog.Text("for huge attribute enhancement. You also have a chance to upgrade its phase by forging,");
                        dialog.Text("fusing, or smelting in the alien world of the Dragon Furnace.\n");

                        dialog.Option("Embed~Anima.", 5);
                        dialog.Avatar(1976).FinalizeDialog();
                        break;
                    }
                case 2:
                    {
                        dialog.Text("Anima contains everlasting vital power that can greatly improve equipment when embedded in");
                        dialog.Text("You may upgrade Animae with the Dragon Furnace. For P12 Anima and above");
                        dialog.Text("you can exchange it for a physical reward. The price of your Anima is:\n");
                        dialog.Text("          +---------------------------------------------------------------------+\n");
                        dialog.Text("              Current Anima Price: " + (Pool.ItemsBase[client.ActiveNpc].ConquerPointsWorth - 1) + " CPs\n");
                        dialog.Text("          +---------------------------------------------------------------------+\n");
                        dialog.Text("Are you sure you want to exchange this Anima for CPs now?\n");

                        // dialog.Option("Yes.", 7);
                        dialog.Option("No,~not~now.", 255);
                        dialog.Avatar(1976).FinalizeDialog();
                        break;
                    }
                case 4:
                    {
                        client.SendSysMesage("https://co.99.com/guide/event/2019/anima/", MsgMessage.ChatMode.WebSite, MsgMessage.MsgColor.red);
                        break;
                    }
                case 5:
                    {
                        client.Send(stream.ActionCreate(new ActionQuery() { Type = ActionType.OpenDialog, ObjId = client.Player.UID, Timestamp = (uint)Time32.timeGetTime().GetHashCode(), dwParam = DialogCommands.EmbedRune, PositionX = client.Player.X, PositionY = client.Player.Y }));

                        break;
                    }
                case 3:
                    {
                        client.SendSysMesage("https://co.99.com/guide/event/anima_introduction.shtml", MsgMessage.ChatMode.WebSite, MsgMessage.MsgColor.red);
                        break;
                    }
                case 7:
                    {
                        if (client.Inventory.Remove(id, 1, stream))
                        {
                            String folderN = DateTime.Now.Year + "-" + DateTime.Now.Month,
                                Path = "Cache\\Logs\\[AnimaExchangeForCps]\\",
                                NewPath = System.IO.Path.Combine(Path, folderN);
                            if (!File.Exists(NewPath + folderN))
                            {
                                System.IO.Directory.CreateDirectory(System.IO.Path.Combine(Path, folderN));
                            }
                            if (!File.Exists(NewPath + "\\" + DateTime.Now.Day + ".txt"))
                            {
                                using (System.IO.FileStream fs = System.IO.File.Create(NewPath + "\\" + DateTime.Now.Day + ".txt"))
                                {
                                    fs.Close();
                                }
                            }
                            using (System.IO.StreamWriter file = new System.IO.StreamWriter(NewPath + "\\" + DateTime.Now.Day + ".txt", true))
                            {
                                file.WriteLine(" UserName[Acc] |" + client.Player.Name + " | UIDAccount | " + client.Player.UID + " | Exchange Anima ID | " + id + " | The Name Of Anima is | " + Pool.ItemsBase[id].Name + " | For Cps = | " + (Pool.ItemsBase[client.ActiveNpc].ConquerPointsWorth - 1) + " [The Clock] " + DateTime.Now.Hour + ":" + DateTime.Now.Minute + ":" + DateTime.Now.Second);
                                file.Close();
                            }
                            client.Player.ConquerPoints += (int)(Pool.ItemsBase[client.ActiveNpc].ConquerPointsWorth - 1);
                            client.CreateBoxDialog("You successfully exchanged a " + Pool.ItemsBase[id].Name + " for " + (Pool.ItemsBase[id].ConquerPointsWorth - 1) + " CPs!");
                        }
                        break;
                    }
                case 10://Forging
                    {
                        if (client.Inventory.Contain(id, 1))
                        {

                            ushort X = 0, Y = 0;
                            Pool.ServerMaps[10428].GetRandCoord(ref X, ref Y);
                            client.Teleport(X, Y, 10428, Pool.ServerMaps[10428].GenerateDynamicID());
                            client.Player.DragonFurnace = id;
                            client.Player.DragonFurnaceForge = 0;
                            client.Player.DragonFurnaceForgeCount = 0;

                            Game.MsgNpc.Npc np = Game.MsgNpc.Npc.Create();
                            np.UID = (uint)NpcID.DragonFurnaceForging;
                            np.NpcType = Role.Flags.NpcType.Talker;
                            np.Mesh = 15370;
                            np.Map = client.Player.Map;
                            np.DynamicID = client.Player.DynamicID;
                            np.X = 54;
                            np.Y = 59;
                            client.Map.AddNpc(np);
                            np.Send(stream);

                            client.CreateBoxDialog("With a strong wind, you were taken to the alien world floor " + id % 100 + ". Go forge your Anima!");
                            client.Player.SendString(stream, MsgStringPacket.StringID.Effect, true, new string[] { "moveback" });
                        }
                        break;
                    }
                case 20://Fusing
                    {
                        if (client.Inventory.Contain(id, 2))
                        {
                            ushort X = 0, Y = 0;
                            Pool.ServerMaps[10428].GetRandCoord(ref X, ref Y);
                            client.Teleport(X, Y, 10428, Pool.ServerMaps[10428].GenerateDynamicID());
                            client.Player.DragonFurnace = id;


                            Pool.ServerMaps[10428].GetRandCoord(ref X, ref Y);
                            client.Map.AddMapMonster(stream, 2984, X, Y, 1, 1, 1, client.Player.DynamicID);

                            Game.MsgNpc.Npc np = Game.MsgNpc.Npc.Create();
                            np.UID = (uint)NpcID.DragonFurnaceFusing;
                            np.NpcType = Role.Flags.NpcType.Talker;
                            np.Mesh = 22850;
                            np.Map = client.Player.Map;
                            np.DynamicID = client.Player.DynamicID;
                            np.X = 54;
                            np.Y = 59;
                            client.Map.AddNpc(np);
                            np.Send(stream);
                            client.Player.View.Role(false);

                            client.CreateBoxDialog("With a strong wind, you were taken to the alien world floor " + id % 100 + ". Go defeat the Ancient Dragon and start fusing your Animae in the Dragon Furnace.");
                            client.Player.SendString(stream, MsgStringPacket.StringID.Effect, true, new string[] { "moveback" });
                        }
                        else
                        {
                            dialog.Text("    Please make sure you have 2 " + Pool.ItemsBase[id].Name + ", first.");

                            dialog.Option("Okay.", 255).FinalizeDialog();
                        }
                        break;
                    }
                case 30://Smelting
                    {
                        if (client.Inventory.Contain(id, 1))
                        {
                            client.Teleport(54, 59, 10428);
                            client.Player.DragonFurnace = 0;
                            client.CreateBoxDialog("With a strong wind, you were taken to the alien world. Go and check which furnace would you like to use to smelt Anima.");
                            client.Player.SendString(stream, MsgStringPacket.StringID.Effect, true, new string[] { "moveback" });
                        }
                        else
                        {
                            dialog.Text("    You can`t enter the alien world since you don`t have 1x P" + id.ToString() + "Anima.");
                            dialog.Option("I`ll~go~collect~some.", 255);
                            dialog.Avatar(1976).FinalizeDialog();
                        }
                        break;
                    }
            }
        }

        public static void RuneFragments(Client.GameClient client, ServerSockets.Packet stream, byte Option, string Input, uint id)
        {
            MsgGameItem item;
            if (client.Inventory.TryGetItem(client.ActiveNpc, out item))
            {
                bool bound = item.ITEM_ID >= 3306369 && item.ITEM_ID <= 3306371;
                if (bound && item.Bound < 1) item.Bound = 1;
                Dialog dialog = new Dialog(client, stream);
                switch (Option)
                {

                    case 0:
                        {
                            dialog.Text("You can combine 20 " + Pool.ItemsBase[item.ITEM_ID].Name + "s into a complete " + Pool.ItemsBase[item.ITEM_ID].Name.Replace("Fragment", "") + ".\n");
                            dialog.Text("If you use this fragment alone, you have a chance of getting 2 fragments.");

                            dialog.Option("Combine~20~fragments.", 1);
                            dialog.Option("Use~1~fragment~for~double.", 2).FinalizeDialog();
                            break;
                        }
                    case 1:
                        {
                            if (client.Inventory.Contain(item.ITEM_ID, 20, item.Bound))
                            {
                                if (client.Inventory.HaveSpace(1))
                                {
                                    if (client.Inventory.Remove(item.ITEM_ID, 20, stream))
                                    {
                                        uint ID = 0;
                                        if (Pool.ItemsBase[item.ITEM_ID].Name.Contains("Blue"))
                                        {
                                            var runes = Pool.ItemsBase.Values.Where(i => Database.ItemType.ItemPosition(i.ID) == (ushort)Role.Flags.ConquerItem.BlueRune && i.ID % 100 == 1);
                                            ID = runes.ToArray()[Pool.GetRandom.Next(0, runes.Count())].ID;
                                        }
                                        else if (Pool.ItemsBase[item.ITEM_ID].Name.Contains("Red"))
                                        {
                                            var runes = Pool.ItemsBase.Values.Where(i => Database.ItemType.ItemPosition(i.ID) == (ushort)Role.Flags.ConquerItem.RedRune && i.ID % 100 == 1);
                                            ID = runes.ToArray()[Pool.GetRandom.Next(0, runes.Count())].ID;
                                        }
                                        else if (Pool.ItemsBase[item.ITEM_ID].Name.Contains("Yellow"))
                                        {
                                            var runes = Pool.ItemsBase.Values.Where(i => Database.ItemType.ItemPosition(i.ID) == (ushort)Role.Flags.ConquerItem.YellowRune && i.ID % 100 == 1);
                                            ID = runes.ToArray()[Pool.GetRandom.Next(0, runes.Count())].ID;
                                        }
                                        client.Inventory.Add(stream, ID, 1, 0, 0, 0, Role.Flags.Gem.NoSocket, Role.Flags.Gem.NoSocket, item.Bound > 0);
                                        client.SendSysMesage("You have got 1 " + Pool.ItemsBase[ID].Name + (bound ? "(B)." : "."));
                                    }
                                }
                                else client.CreateBoxDialog("Please make sure you have 1 free slot in your inventory.");
                            }
                            else client.CreateBoxDialog("Please make sure you have 20 fragments to make a Rune.");
                            break;
                        }
                    case 2:
                        {
                            if (Role.Core.Rate(50))
                            {
                                client.Inventory.RemoveStackItem(item.UID, 1, stream);
                                client.CreateBoxDialog("Failed to combine. The magic of the fragment has vanished, and it disappeared.");
                            }
                            else
                            {
                                client.Inventory.AddItemWitchStack(item.ITEM_ID, 0, 1, stream, item.Bound > 0);
                                client.CreateBoxDialog("Congratulations! You successfully made 2 " + Pool.ItemsBase[item.ITEM_ID].Name + "s!");
                            }
                            break;
                        }

                }
            }
        }

