        [NpcAttribute(NpcID.MarketShop)]
        public static void MarketShop(Client.GameClient client, ServerSockets.Packet stream, byte Option, string Input, uint id)
        {
            Dialog dialog = new Dialog(client, stream);
            switch (Option)
            {
                case 0: goto case 50;
                case 50:
                    {
                        dialog.Text("Hello there, i can sell you cool items for cool prices.\n");
                        dialog.Text("Wanna proceed? Here are my options.\n");

                        dialog.Option("Super Thunder Gem[2,099 CPs].", 1);
                        dialog.Option("Super Glory Gem[2,099 CPs].", 2);
                        dialog.Option("Super Infinity Gem[2,499 CPs].", 9);
                        dialog.Option("Next.", 51);
                        dialog.Option("I~see.", 255).FinalizeDialog();
                        break;
                    }
                case 51:
                    {
                        dialog.Text("Hello there, i can sell you cool items for cool prices.\n");
                        dialog.Text("Wanna proceed? Here are my options.\n");

                        dialog.Option("Meteor Scroll[29 CPs].", 5);
                        dialog.Option("Super Meteor Scroll[299 CPs].", 10);
                        dialog.Option("DB Scroll[2,149 CPs].", 8);
                        dialog.Option("Super DB Scroll[21,490 CPs].", 11);
                        dialog.Option("Next.", 52);
                        dialog.Option("Previous.", 50).FinalizeDialog();
                        break;
                    }
                case 52:
                    {
                        dialog.Text("Hello there, i can sell you cool items for cool prices.\n");
                        dialog.Text("Wanna proceed? Here are my options.\n");

                        dialog.Option("Oblivion Dew[149 CPs].", 7);
                        dialog.Option("Penitence Amulet[999 CPs].", 30);
                        // dialog.Option("20~YellowRuneFragment(s)[2499 CPs].", 3);
                        dialog.Option("Tough Drill[2,499 CPs].", 4);
                        dialog.Option("Next.", 100);
                        dialog.Option("Previous.", 51).FinalizeDialog();
                        break;
                    }
                case 100:
                    {
                        dialog.Text("Hello there, i can sell you cool items for cool prices.\n");
                        dialog.Text("Wanna proceed? Here are my options.\n");

                        //    dialog.Text("<tip color=0xfff05050 desc=Drops#10-15#Conquer#Points#per#monster#(5-10#Conquer#Points#While#Auto#Hunting)#.>VIP 4</tip> => 2000 Online Points per 12 hours.\n");
                        dialog.Text("<tip color=0xfff05050 desc=Drops#20-25#Conquer#Points#per#monster#(15-20#Conquer#Points#While#Auto#Hunting)#.>VIP 6</tip> => 499,999 Conquer Points per 6 hours.\n");



                        dialog.Option("6-hour VIP 6[499,999 CPs].", 21);
                        dialog.Option("Previous.", 52);
                        dialog.Option("I~see.", 255).FinalizeDialog();
                        break;
                    }
                case 21:
                    {
                        if (client.Player.ConquerPoints >= 499999)
                        {
                            if (client.Player.VipLevel == 0)
                            {
                                client.Player.ConquerPoints -= 499999;
                                client.Player.ExpireVip = DateTime.Now.AddHours(6);

                                client.Player.VipLevel = 6;
                                client.Player.SendUpdate(stream, client.Player.VipLevel, MsgUpdate.DataType.VIPLevel);

                                client.Player.UpdateVip(stream);
                                client.SendSysMesage("You have 6 hour(s) of VIP service remaining.", MsgMessage.ChatMode.System, MsgMessage.MsgColor.red);
                                dialog.Text("Congratulations! You've got 6-hour VIP 6 Service!");

                                dialog.Option("Thanks.", 255).FinalizeDialog();
                            }
                            else
                            {
                                dialog.Text("Hey hey! you already have VIP " + client.Player.VipLevel + "!");

                                dialog.Option("I~see.", 255).FinalizeDialog();
                            }
                        }
                        else
                        {
                            dialog.Text("Hey hey! you don't have the required amount of Conquer Points!");

                            dialog.Option("I~see.", 255).FinalizeDialog();
                        }
                        break;
                    }
                default:
                    {
                        uint ID = 0, cost = 2499;
                        byte count = 1;
                        switch (Option)
                        {
                            case 1: ID = 700103; cost = 2099; break;
                            case 2: ID = 700123; cost = 2099; break;
                            // case 3: ID = 3306367; count = 20; break;
                            case 4: ID = Database.ItemType.ToughDrill; break;
                            case 5: ID = Database.ItemType.MeteorScroll; cost = 29; break;
                            case 7: ID = 711083; cost = 149; break;
                            case 8: ID = Database.ItemType.DragonBallScroll; cost = 2149; break;
                            case 9: ID = 700133; break;
                            case 10: ID = Database.ItemType.SuperMeteorScroll; cost = 299; break;
                            case 11: ID = Database.ItemType.SuperDBScroll; cost = 21490; break;
                            case 30: ID = 723727; cost = 999; break;
                        }
                        if (ID > 0)
                        {
                            if (client.Player.ConquerPoints >= cost)
                            {
                                if (count > 1 ? client.Inventory.AddItemWitchStack(ID, 0, count, stream) : client.Inventory.Add(stream, ID, count))
                                {
                                    client.Player.ConquerPoints -= (int)cost;
                                    dialog.Text("Congratulations! You've got " + count + " " + Pool.ItemsBase[ID].Name + "(s)!");

                                    dialog.Option("Thanks.", 255).FinalizeDialog();
                                }
                                else
                                {
                                    dialog.Text("Hey hey! you don't have enough space in your inventory!");

                                    dialog.Option("I~see.", 255).FinalizeDialog();
                                }
                            }
                            else
                            {
                                dialog.Text("Hey hey! you don't have the required amount of Conquer Points!");

                                dialog.Option("I~see.", 255).FinalizeDialog();
                            }
                        }
                        break;
                    }

            }
        }

