        [NpcAttribute(NpcID.HuntingArea)]
        public static void HuntingArea(Client.GameClient client, ServerSockets.Packet stream, byte Option, string Input, uint id)
        {
            Dialog dialog = new Dialog(client, stream);
            switch (Option)
            {
                case 0:
                    {
                        dialog.Text("Hello there, i can teleport you to my hunting map.\n");
                        dialog.Text("There, many monsters as fuck, you can collect a lot of Conquer Points by hunting.\n");
                        dialog.Text("In red devil's maps, the monsters are a bit stronger and a less than pheasant's map.\n");

                        dialog.Option("Red~Devils[1000 CPs].", 1);
                        dialog.Option("Pheasants[2000 CPs].", 2);
                        dialog.Option("I~see.", 255).FinalizeDialog();
                        break;
                    }
                case 1:
                    {
                        if (client.Player.ConquerPoints >= 1000)
                        {
                            client.Player.ConquerPoints -= 1000;
                            client.Teleport(19, 127, 2351);
                            client.CreateBoxDialog("You've been teleported to red devil's map.");
                        }
                        else
                        {
                            dialog.Text("Hey, are you making fun on me? you don't have the required amount of Conquer Points.\n");

                            dialog.Option("My~bad.", 255).FinalizeDialog();
                        }
                        break;
                    }
                case 2:
                    {
                        if (client.Player.ConquerPoints >= 2000)
                        {
                            client.Player.ConquerPoints -= 2000;
                            client.Teleport(19, 127, 2352);
                            client.CreateBoxDialog("You've been teleported to pheasant's map.");
                        }
                        else
                        {
                            dialog.Text("Hey, are you making fun on me? you don't have the required amount of Conquer Points.\n");

                            dialog.Option("My~bad.", 255).FinalizeDialog();
                        }
                        break;
                    }
            }
        }
        [NpcAttribute(NpcID.HeroPointes)]
        public static void HeroPointes(Client.GameClient client, ServerSockets.Packet stream, byte Option, string Input, uint id)
        {
            Dialog data = new Dialog(client, stream);
            switch (Option)
            {
                case 0:
                    {
                        data.AddText("The HeroOfGame Winners of the Game [3] Times have Prizes AnimaP12. The times you won [ <tip color=0xffc501e7> [" + client.Player.HeroPointes + "] </tip> ].")
                        .AddOption("Did You Win ( 3 )", 1)
                       .AddOption("or not", 255).AddAvatar(10).FinalizeDialog();
                        break;
                    }
                case 1:
                    {
                        if (client.Player.HeroPointes >= 3)
                        {

                            client.Player.HeroPointes -= 3;
                            Random R = new Random();
                            int Nr = R.Next(2, 4);
                            {
                                if (Nr == 1) client.Inventory.AddItemWitchStack(4320002, 0, 1, stream);
                                if (Nr == 2) client.Inventory.AddItemWitchStack(4310002, 0, 1, stream);
                                if (Nr == 3) client.Inventory.AddItemWitchStack(4310001, 0, 1, stream);
                                if (Nr == 4) client.Inventory.AddItemWitchStack(4310000, 0, 1, stream);
                            }
                            client.Inventory.AddItemWitchStack(4100012, 0, 1, stream);
                            data.AddOption("thanks! ", 255).AddAvatar(0).FinalizeDialog();
                        }
                        else
                        {
                            data.AddText("Where your [ <tip color=0xffc501e7>[" + client.Player.HeroPointes + "] </tip> ]!. ");
                            data.AddOption("i'm Sorry ", 255).AddAvatar(0).FinalizeDialog();
                            break;
                        }

                    }
                    break;
            }

        }

